insert into public.therapist_resources (slug, title, kind, summary, goal, audience, duration, body_md, fields, tags, created_at)
values
  ('weekend-reset-intention-planner', 'Weekend Reset Intention Planner', 'worksheet'::resource_kind, 'A planner for choosing a few restful and meaningful things to do before the week starts.', 'Use it to help a client shape a weekend that restores them instead of just filling time.', array['Adults', 'Teens']::text[], '20 minutes', 'Walk through the weekend day by day and have the client mark one anchor activity for each. Ask what restores them versus what only passes time. Keep the plan loose enough to survive a surprise, and review how it went at the next session.', '[{"id": "f0", "type": "textarea", "label": "What I want my weekend to feel like:"}, {"id": "f1", "type": "textarea", "label": "One thing I need to get done:"}, {"id": "f2", "type": "textarea", "label": "One thing that restores me:"}, {"id": "f3", "type": "textarea", "label": "Who I might spend time with:"}, {"id": "f4", "type": "textarea", "label": "What could get in the way, and my backup:"}]'::jsonb, array['planning', 'routines', 'self-care']::text[], '2026-11-08T15:00:00+00:00'::timestamptz),
  ('pocket-evidence-notebook-page', 'Pocket Evidence Notebook Page', 'worksheet'::resource_kind, 'A running page where a client jots down small moments that fit a kinder view of themselves.', 'Use it to help a client collect everyday evidence that balances a harsh inner story.', array['Adults', 'Teens']::text[], 'Five minutes daily for two weeks', 'Give the client a page to fill briefly each evening with one moment, however small. The habit matters more than the size of the entry. When reviewing, read the entries aloud and ask what the client notices about the pattern, without arguing them into anything.', '[{"id": "f0", "type": "textarea", "label": "Today''s small moment:"}, {"id": "f1", "type": "textarea", "label": "What I did or what happened:"}, {"id": "f2", "type": "textarea", "label": "What it says about me, in my own words:"}, {"id": "f3", "type": "textarea", "label": "The harsh story it does not fit:"}, {"id": "f4", "type": "textarea", "label": "What I want to remember from this week:"}]'::jsonb, array['self-esteem', 'strengths', 'self-monitoring']::text[], '2026-11-08T15:00:00+00:00'::timestamptz),
  ('decision-balance-sheet-with-a-values-lens', 'Decision Balance Sheet With a Values Lens', 'worksheet'::resource_kind, 'A decision page with a column for what each option says about what the client cares about.', 'Use it to help a client weigh a choice by values as well as by pros and cons.', array['Adults', 'Teens']::text[], '30 minutes', 'Set out two options and fill the usual pros and cons, then add a values column asking what each option would honor. Notice when the client''s head and gut disagree and slow down there. The choice stays theirs; the page just makes the reasoning visible.', '[{"id": "f0", "type": "textarea", "label": "The decision I am facing:"}, {"id": "f1", "type": "textarea", "label": "Option one, pros and cons:"}, {"id": "f2", "type": "textarea", "label": "Option two, pros and cons:"}, {"id": "f3", "type": "textarea", "label": "What each option would honor in me:"}, {"id": "f4", "type": "textarea", "label": "What I lean toward today and why:"}]'::jsonb, array['planning', 'values', 'decisions']::text[], '2026-11-08T15:00:00+00:00'::timestamptz),
  ('fresh-start-morning-sequence-sheet', 'Fresh Start Morning Sequence Sheet', 'worksheet'::resource_kind, 'A sheet for designing a short, doable morning sequence that starts the day on the client''s terms.', 'Use it to help a client build a small morning routine they can keep going.', array['Adults', 'Teens']::text[], '25 minutes', 'Ask what mornings look like now, then pick two or three steps that take under ten minutes in all. Fewer steps survive longer. Plan what happens on a rushed day so one missed morning does not end the whole routine.', '[{"id": "f0", "type": "textarea", "label": "What my mornings look like now:"}, {"id": "f1", "type": "textarea", "label": "Three small steps I would like to add:"}, {"id": "f2", "type": "textarea", "label": "How long each will take:"}, {"id": "f3", "type": "textarea", "label": "What I do on a rushed day:"}, {"id": "f4", "type": "textarea", "label": "How I will remind myself:"}]'::jsonb, array['routines', 'habits', 'planning']::text[], '2026-11-08T15:00:00+00:00'::timestamptz),
  ('support-circle-contact-map', 'Support Circle Contact Map', 'worksheet'::resource_kind, 'A page that maps the people and places a client can turn to for different kinds of support.', 'Use it to help a client see who they can reach for practical, emotional and fun support.', array['Adults', 'Teens']::text[], '25 minutes', 'Draw three rings and have the client place people or groups in each, then notice any ring that is thin. Talk about one small step to strengthen it. Some clients have few names; that is useful information, and the aim is one realistic next contact.', '[{"id": "f0", "type": "textarea", "label": "People I can call when I need practical help:"}, {"id": "f1", "type": "textarea", "label": "People I can talk to when I feel low:"}, {"id": "f2", "type": "textarea", "label": "People I enjoy having fun with:"}, {"id": "f3", "type": "textarea", "label": "A ring that feels thin:"}, {"id": "f4", "type": "textarea", "label": "One person I will reach out to this week:"}]'::jsonb, array['support', 'connection', 'planning']::text[], '2026-11-08T15:00:00+00:00'::timestamptz),
  ('evidence-for-and-against-scales-sheet', 'Evidence For and Against Scales Sheet', 'cbt'::resource_kind, 'A sheet where a client lists evidence on both sides of a thought and then rerates their belief.', 'Use it to help a client test how strongly they believe a thought against the facts.', array['Adults', 'Teens']::text[], '30 minutes', 'Start with one specific thought and have the client rate belief from 0 to 100. Fill both columns before drawing any conclusion, and ask for facts a stranger could verify rather than feelings. Rerate at the end; a small shift is still movement.', '[{"id": "f0", "type": "textarea", "label": "The thought I am testing:"}, {"id": "f1", "type": "textarea", "label": "How strongly I believe it, 0 to 100:"}, {"id": "f2", "type": "textarea", "label": "Facts that support it:"}, {"id": "f3", "type": "textarea", "label": "Facts that do not fit it:"}, {"id": "f4", "type": "textarea", "label": "A more balanced thought:"}, {"id": "f5", "type": "textarea", "label": "How strongly I believe the first thought now:"}]'::jsonb, array['core CBT', 'thought record', 'thinking traps']::text[], '2026-11-08T15:00:00+00:00'::timestamptz),
  ('activity-and-mood-hour-by-hour-grid', 'Activity and Mood Hour-by-Hour Grid', 'cbt'::resource_kind, 'A daily grid where a client logs what they did each part of the day and rates mood and mastery.', 'Use it to help a client spot which activities lift or lower their mood.', array['Adults', 'Teens']::text[], 'One week of daily logging', 'Ask for brief entries at three or four points each day rather than every hour, so it stays doable. At the next visit, look for activities that rate higher on mood or sense of accomplishment and ask what the client makes of them. Keep it curious, not corrective.', '[{"id": "f0", "type": "textarea", "label": "Morning: what I did and my mood, 0 to 10:"}, {"id": "f1", "type": "textarea", "label": "Afternoon: what I did and my mood, 0 to 10:"}, {"id": "f2", "type": "textarea", "label": "Evening: what I did and my mood, 0 to 10:"}, {"id": "f3", "type": "textarea", "label": "An activity that gave me a sense of accomplishment:"}, {"id": "f4", "type": "textarea", "label": "An activity I want to try more of:"}]'::jsonb, array['behavioral activation', 'self-monitoring', 'core CBT']::text[], '2026-11-08T15:00:00+00:00'::timestamptz),
  ('downward-arrow-thought-drill-down', 'Downward Arrow Thought Drill-Down', 'cbt'::resource_kind, 'A step-by-step page that follows a thought down to the belief underneath it.', 'Use it to help a client find the core belief sitting under a surface thought.', array['Adults', 'Teens']::text[], '30 minutes', 'Pick a recent upsetting thought and ask, "If that were true, what would it mean about you?" again and again until the client lands on a core belief. Go gently and stop if the client is flooded. Close by naming the belief as an idea, not a fact, and do not push to challenge it in the same session.', '[{"id": "f0", "type": "textarea", "label": "The upsetting thought:"}, {"id": "f1", "type": "textarea", "label": "If that were true, what would it mean:"}, {"id": "f2", "type": "textarea", "label": "And if that were true, what then:"}, {"id": "f3", "type": "textarea", "label": "The belief I land on:"}, {"id": "f4", "type": "textarea", "label": "Where I may have learned it:"}, {"id": "f5", "type": "textarea", "label": "A kinder way to hold it:"}]'::jsonb, array['core beliefs', 'core CBT', 'automatic thoughts']::text[], '2026-11-08T15:00:00+00:00'::timestamptz),
  ('behavioral-experiment-prediction-planner', 'Behavioral Experiment Prediction Planner', 'cbt'::resource_kind, 'A planner for testing a feared prediction by doing something and comparing what happened.', 'Use it to help a client check a prediction against real experience.', array['Adults', 'Teens']::text[], '30 minutes to plan, then a week', 'Help the client turn a worry into a specific prediction they can check, with a rating of how sure they are. Plan a small experiment, note what else could explain the result, and review together what actually happened versus what they predicted.', '[{"id": "f0", "type": "textarea", "label": "My prediction in one sentence:"}, {"id": "f1", "type": "textarea", "label": "How sure I am, 0 to 100:"}, {"id": "f2", "type": "textarea", "label": "The experiment I will run:"}, {"id": "f3", "type": "textarea", "label": "What actually happened:"}, {"id": "f4", "type": "textarea", "label": "What I learned, and what I will try next:"}]'::jsonb, array['behavioral experiment', 'core CBT', 'exposure']::text[], '2026-11-08T15:00:00+00:00'::timestamptz),
  ('worry-time-container-log', 'Worry Time Container Log', 'cbt'::resource_kind, 'A log for postponing worries to one set time and sorting them there into solvable and not.', 'Use it to help a client contain worry to a set window and act on what can be acted on.', array['Adults', 'Teens']::text[], 'Ten minutes daily for two weeks', 'Choose a daily worry window and a place to jot worries as they pop up during the day. At the window, sort each into something to act on or something to let be. Expect it to be messy at first; the skill is returning to the day each time.', '[{"id": "f0", "type": "textarea", "label": "My worry window, time and place:"}, {"id": "f1", "type": "textarea", "label": "Worries I jotted during the day:"}, {"id": "f2", "type": "textarea", "label": "Ones I can do something about:"}, {"id": "f3", "type": "textarea", "label": "The first small step for one of them:"}, {"id": "f4", "type": "textarea", "label": "Ones I will let sit for now:"}]'::jsonb, array['worry', 'anxiety', 'core CBT']::text[], '2026-11-08T15:00:00+00:00'::timestamptz),
  ('passengers-on-the-bus-values-drive-sheet', 'Passengers on the Bus Values Drive Sheet', 'act'::resource_kind, 'A sheet for naming difficult thoughts as passengers while the client steers toward what matters.', 'Use it to help a client keep driving toward their values with hard thoughts along for the ride.', array['Adults', 'Teens']::text[], '30 minutes', 'Use the bus metaphor: the client is the driver, the loud thoughts and feelings are passengers who cannot take the wheel. Have them name a direction first and the passengers second. Go lightly on the metaphor if it feels like a lecture and let the client make it theirs.', '[{"id": "f0", "type": "textarea", "label": "Where I want to drive my life:"}, {"id": "f1", "type": "textarea", "label": "The passengers who show up and what they say:"}, {"id": "f2", "type": "textarea", "label": "How I usually respond to them:"}, {"id": "f3", "type": "textarea", "label": "What I could do with them aboard:"}, {"id": "f4", "type": "textarea", "label": "One turn I will make this week:"}]'::jsonb, array['values', 'defusion', 'core ACT']::text[], '2026-11-08T15:00:00+00:00'::timestamptz),
  ('hands-as-thoughts-unhooking-exercise-card', 'Hands as Thoughts Unhooking Exercise Card', 'act'::resource_kind, 'A short card for holding thoughts at different distances and noticing the shift in what the client can do.', 'Use it to help a client feel the difference between being tangled in a thought and holding it at a distance.', array['Adults', 'Teens']::text[], '10 minutes', 'Have the client press hands over their face as if the thought is that close, then lower them into their lap and notice the difference. Ask what they could do from each position. Pair it with a sentence like "I am having the thought that..." if it helps.', '[{"id": "f0", "type": "textarea", "label": "A thought that grabs me:"}, {"id": "f1", "type": "textarea", "label": "What it is like with the thought right up close:"}, {"id": "f2", "type": "textarea", "label": "What it is like with the thought held away:"}, {"id": "f3", "type": "textarea", "label": "What I could do from that distance:"}, {"id": "f4", "type": "textarea", "label": "When I might use this:"}]'::jsonb, array['defusion', 'core ACT', 'mindfulness']::text[], '2026-11-08T15:00:00+00:00'::timestamptz),
  ('willingness-dial-for-one-hard-step', 'Willingness Dial for One Hard Step', 'act'::resource_kind, 'A dial from reluctant to willing for one valued action the client has been avoiding.', 'Use it to help a client pick a step and find their willingness to take it with discomfort along.', array['Adults', 'Teens']::text[], '20 minutes', 'Name one valued action and rate willingness from 0 to 10, then ask what would raise it by one point. Willingness is not wanting; make room for the client to do it while still dreading it. Shrink the step until the dial is at six or higher.', '[{"id": "f0", "type": "textarea", "label": "The valued action I have been avoiding:"}, {"id": "f1", "type": "textarea", "label": "My willingness today, 0 to 10:"}, {"id": "f2", "type": "textarea", "label": "What I expect to feel if I do it:"}, {"id": "f3", "type": "textarea", "label": "A smaller version I could take:"}, {"id": "f4", "type": "textarea", "label": "What I will do, and when:"}]'::jsonb, array['willingness', 'committed action', 'core ACT']::text[], '2026-11-08T15:00:00+00:00'::timestamptz),
  ('sky-and-weather-observing-self-page', 'Sky and Weather Observing Self Page', 'act'::resource_kind, 'A page that uses the image of the sky holding any weather to practice noticing from a steady place.', 'Use it to help a client practice noticing feelings from a steady observing view.', array['Adults', 'Teens']::text[], '15 minutes', 'Invite the client to describe the weather of the moment, such as storm, fog or sun, then to notice the part of them that is watching. Spend time on the sky that is not changed by the weather. If a client finds this abstract, draw it.', '[{"id": "f0", "type": "textarea", "label": "The weather inside me right now:"}, {"id": "f1", "type": "textarea", "label": "How it moves or changes:"}, {"id": "f2", "type": "textarea", "label": "The part of me that notices it:"}, {"id": "f3", "type": "textarea", "label": "What stays the same underneath:"}, {"id": "f4", "type": "textarea", "label": "A time I could use this view this week:"}]'::jsonb, array['mindfulness', 'acceptance', 'core ACT']::text[], '2026-11-08T15:00:00+00:00'::timestamptz),
  ('values-to-daily-actions-bridge-builder', 'Values to Daily Actions Bridge Builder', 'act'::resource_kind, 'A bridge diagram linking a stated value to a specific action this week.', 'Use it to help a client turn a value into a concrete, doable action.', array['Adults', 'Teens']::text[], '25 minutes', 'Start with one value in the client''s words, then build the bridge: what it looks like in action, what small step this week, and what barrier might show up. Ask for something specific enough to film. Revisit the bridge at the next session instead of rewriting it.', '[{"id": "f0", "type": "textarea", "label": "A value that matters to me:"}, {"id": "f1", "type": "textarea", "label": "What it would look like in action:"}, {"id": "f2", "type": "textarea", "label": "One specific thing I will do this week:"}, {"id": "f3", "type": "textarea", "label": "A barrier that might show up:"}, {"id": "f4", "type": "textarea", "label": "How I will respond to the barrier:"}]'::jsonb, array['values', 'committed action', 'core ACT']::text[], '2026-11-08T15:00:00+00:00'::timestamptz),
  ('wise-mind-three-circles-worksheet', 'Wise Mind Three Circles Worksheet', 'dbt'::resource_kind, 'A worksheet using emotion mind, reasonable mind and wise mind for a recent decision.', 'Use it to help a client find what wise mind says when feeling and logic pull apart.', array['Adults', 'Teens']::text[], '25 minutes', 'Choose a recent choice or a pending one. Have the client fill emotion mind and reasonable mind, then pause and ask what both hold that is true. Wise mind often arrives as a quiet sense, so allow silence and do not supply the answer.', '[{"id": "f0", "type": "textarea", "label": "The situation:"}, {"id": "f1", "type": "textarea", "label": "What emotion mind says:"}, {"id": "f2", "type": "textarea", "label": "What reasonable mind says:"}, {"id": "f3", "type": "textarea", "label": "What wise mind says:"}, {"id": "f4", "type": "textarea", "label": "How I know it is wise mind:"}]'::jsonb, array['core DBT', 'mindfulness', 'skills']::text[], '2026-11-08T15:00:00+00:00'::timestamptz),
  ('pros-and-cons-of-acting-on-the-urge-sheet', 'Pros and Cons of Acting on the Urge Sheet', 'dbt'::resource_kind, 'A four-box sheet weighing acting on an urge against tolerating it.', 'Use it to help a client weigh short-term and long-term outcomes of an urge to act.', array['Adults', 'Teens']::text[], '25 minutes', 'Use the four boxes: pros and cons of acting on the urge, and pros and cons of resisting. Fill it when calm, not mid-urge, so the client can reread it when the urge returns. If the urge involves self-harm, include 988 (call or text) and complete it in session.', '[{"id": "f0", "type": "textarea", "label": "The urge I am looking at:"}, {"id": "f1", "type": "textarea", "label": "Pros of acting on it:"}, {"id": "f2", "type": "textarea", "label": "Cons of acting on it:"}, {"id": "f3", "type": "textarea", "label": "Pros of resisting it:"}, {"id": "f4", "type": "textarea", "label": "Cons of resisting it:"}, {"id": "f5", "type": "textarea", "label": "If I am in danger, I will call or text 988 or my safety contact:"}]'::jsonb, array['distress tolerance', 'urges', 'core DBT']::text[], '2026-11-08T15:00:00+00:00'::timestamptz),
  ('check-the-facts-emotion-fit-card', 'Check the Facts Emotion Fit Card', 'dbt'::resource_kind, 'A card for checking whether the intensity of an emotion fits the facts of a situation.', 'Use it to help a client test whether an emotion and its strength match what happened.', array['Adults', 'Teens']::text[], '20 minutes', 'Walk through the DBT steps: name the emotion, what set it off, the interpretation, and whether the facts fit. If the emotion fits, the next step is problem solving; if not, it is acting differently. Praise honest checking, even when the answer is that the emotion fits.', '[{"id": "f0", "type": "textarea", "label": "The emotion and how strong it is, 0 to 100:"}, {"id": "f1", "type": "textarea", "label": "What happened, facts only:"}, {"id": "f2", "type": "textarea", "label": "The story I told about it:"}, {"id": "f3", "type": "textarea", "label": "Does the emotion fit the facts:"}, {"id": "f4", "type": "textarea", "label": "What I will do next:"}]'::jsonb, array['emotion regulation', 'core DBT', 'skills']::text[], '2026-11-08T15:00:00+00:00'::timestamptz),
  ('turning-the-mind-back-to-acceptance-tally', 'Turning the Mind Back to Acceptance Tally', 'dbt'::resource_kind, 'A log for the moments a client turns the mind back to acceptance of something they cannot change.', 'Use it to help a client practice turning toward acceptance again and again.', array['Adults', 'Teens']::text[], 'One week of daily entries', 'Name one situation that is outside the client''s control and track each time they turn the mind back toward accepting it. Acceptance is not approval; say so plainly. Expect to turn the mind many times a day and treat each return as the skill.', '[{"id": "f0", "type": "textarea", "label": "What I am struggling to accept:"}, {"id": "f1", "type": "textarea", "label": "What fighting it feels like:"}, {"id": "f2", "type": "textarea", "label": "How I turned my mind toward acceptance today:"}, {"id": "f3", "type": "textarea", "label": "What I said to myself:"}, {"id": "f4", "type": "textarea", "label": "What I noticed afterward:"}]'::jsonb, array['acceptance', 'core DBT', 'distress tolerance']::text[], '2026-11-08T15:00:00+00:00'::timestamptz),
  ('do-the-opposite-emotion-trial-sheet', 'Do the Opposite Emotion Trial Sheet', 'dbt'::resource_kind, 'A sheet for picking an emotion, naming its urge and trying the opposite when the emotion does not fit.', 'Use it to help a client try the opposite of an unhelpful emotional urge.', array['Adults', 'Teens']::text[], '25 minutes', 'Choose an emotion that does not fit the facts, such as shame or fear about something safe, and name its urge. The opposite action is done all the way, including body posture and tone. Plan it for a low-stakes situation first.', '[{"id": "f0", "type": "textarea", "label": "The emotion and its urge:"}, {"id": "f1", "type": "textarea", "label": "Does the emotion fit the facts:"}, {"id": "f2", "type": "textarea", "label": "The opposite action I could take:"}, {"id": "f3", "type": "textarea", "label": "How I will do it all the way:"}, {"id": "f4", "type": "textarea", "label": "What I noticed afterward:"}]'::jsonb, array['opposite action', 'emotion regulation', 'core DBT']::text[], '2026-11-08T15:00:00+00:00'::timestamptz),
  ('weekly-state-of-us-check-in-card', 'Weekly State of Us Check-In Card', 'couples'::resource_kind, 'A short card for a weekly talk where each partner says what is working and what needs care.', 'Use it to help partners keep a regular, calm check-in on their relationship.', array['Couples']::text[], '30 minutes weekly', 'Set a time that is not in the middle of a conflict. Each partner has uninterrupted time, then the other reflects back what they heard. Begin with appreciation and keep complaints to one topic at a time; stop and pause if either partner is flooded.', '[{"id": "f0", "type": "textarea", "label": "Partner A: One thing that went well this week:"}, {"id": "f1", "type": "textarea", "label": "Partner B: One thing that went well this week:"}, {"id": "f2", "type": "textarea", "label": "Partner A: Something I need more of:"}, {"id": "f3", "type": "textarea", "label": "Partner B: Something I need more of:"}, {"id": "f4", "type": "textarea", "label": "One thing we will each do this week:"}]'::jsonb, array['couples', 'communication', 'Gottman']::text[], '2026-11-08T15:00:00+00:00'::timestamptz),
  ('stress-reducing-conversation-turn-taking-sheet', 'Stress-Reducing Conversation Turn-Taking Sheet', 'couples'::resource_kind, 'A sheet for partners to take turns talking about outside stress while the other listens without fixing.', 'Use it to help partners support each other through stress that is not about the relationship.', array['Couples']::text[], '30 minutes', 'One partner talks about a stressor for about ten minutes while the other asks questions and shows understanding without advice. Then switch. Coach the listener to take the stressor''s side and hold back solutions unless asked.', '[{"id": "f0", "type": "textarea", "label": "Partner A: What is stressing me right now:"}, {"id": "f1", "type": "textarea", "label": "Partner B: What I heard and how I can show support:"}, {"id": "f2", "type": "textarea", "label": "Partner B: What is stressing me right now:"}, {"id": "f3", "type": "textarea", "label": "Partner A: What I heard and how I can show support:"}, {"id": "f4", "type": "textarea", "label": "What helped, and what we want to repeat:"}]'::jsonb, array['couples', 'support', 'Gottman']::text[], '2026-11-08T15:00:00+00:00'::timestamptz),
  ('small-rituals-for-staying-close-planner', 'Small Rituals for Staying Close Planner', 'couples'::resource_kind, 'A planner for partners to pick small daily and weekly rituals that keep them close.', 'Use it to help partners build small, repeatable moments of connection.', array['Couples']::text[], '30 minutes', 'Ask what rituals the partners already have, such as a coffee together or a goodbye kiss, and add one or two they both want. Small and regular beats grand and rare. Check in on whether they are happening and adjust without blame.', '[{"id": "f0", "type": "textarea", "label": "Partner A: A small ritual I would love:"}, {"id": "f1", "type": "textarea", "label": "Partner B: A small ritual I would love:"}, {"id": "f2", "type": "textarea", "label": "Rituals we already have that we want to keep:"}, {"id": "f3", "type": "textarea", "label": "One new daily ritual we will try:"}, {"id": "f4", "type": "textarea", "label": "One new weekly ritual we will try:"}]'::jsonb, array['connection', 'couples', 'routines']::text[], '2026-11-08T15:00:00+00:00'::timestamptz),
  ('dreams-within-conflict-exploration-guide', 'Dreams Within Conflict Exploration Guide', 'couples'::resource_kind, 'A guide for each partner to share the hope or story under a stuck disagreement.', 'Use it to help partners hear the meaning beneath a recurring disagreement.', array['Couples']::text[], '40 minutes', 'Pick a recurring disagreement and have each partner share what it means to them, their history with it and what they hope for. The listener only asks and reflects; no problem solving yet. Look for a dream underneath each position.', '[{"id": "f0", "type": "textarea", "label": "The disagreement we keep having:"}, {"id": "f1", "type": "textarea", "label": "Partner A: What it means to me and where it comes from:"}, {"id": "f2", "type": "textarea", "label": "Partner B: What it means to me and where it comes from:"}, {"id": "f3", "type": "textarea", "label": "Partner A: The dream underneath my position:"}, {"id": "f4", "type": "textarea", "label": "Partner B: The dream underneath my position:"}, {"id": "f5", "type": "textarea", "label": "One thing we understand better now:"}]'::jsonb, array['conflict', 'couples', 'Gottman']::text[], '2026-11-08T15:00:00+00:00'::timestamptz),
  ('repair-attempt-phrase-menu', 'Repair Attempt Phrase Menu', 'couples'::resource_kind, 'A menu of phrases partners can use to ease tension in the middle of a hard talk.', 'Use it to help partners choose repair phrases that work for them before they need them.', array['Couples']::text[], '20 minutes', 'Have partners pick phrases from a short menu, such as "Can we take a break?" or "I can see your point," and agree how to receive a repair when it is offered. Rehearse in a mild moment. The receiver has a job too: accept the attempt, even if clumsy.', '[{"id": "f0", "type": "textarea", "label": "Partner A: Phrases that would help me:"}, {"id": "f1", "type": "textarea", "label": "Partner B: Phrases that would help me:"}, {"id": "f2", "type": "textarea", "label": "A phrase we will each try:"}, {"id": "f3", "type": "textarea", "label": "How we will accept a repair attempt:"}, {"id": "f4", "type": "textarea", "label": "Our signal if we need a break:"}]'::jsonb, array['repair', 'communication', 'couples']::text[], '2026-11-08T15:00:00+00:00'::timestamptz),
  ('daily-feelings-weather-dial-craft', 'Daily Feelings Weather Dial Craft', 'kids'::resource_kind, 'A craft where a child builds a weather station that shows how they feel each day.', 'Use it to help a child name feelings by moving a weather piece each day.', array['Children']::text[], '30 minutes plus a daily check', 'Have the child draw and cut out sun, cloud, rain and storm pieces and make a board with a clip or arrow. The parent moves it with the child at a regular time and listens without fixing. Keep it playful, and say there is no wrong weather.', '[{"id": "f0", "type": "textarea", "label": "Draw your weather today:"}, {"id": "f1", "type": "textarea", "label": "What happened to make it that way:"}, {"id": "f2", "type": "textarea", "label": "Where you feel it in your body:"}, {"id": "f3", "type": "textarea", "label": "Who you can tell about it:"}, {"id": "f4", "type": "textarea", "label": "What parent does at check-in time:"}]'::jsonb, array['children', 'emotion identification', 'art']::text[], '2026-11-08T15:00:00+00:00'::timestamptz),
  ('brave-backpack-coping-tools-drawing', 'Brave Backpack Coping Tools Drawing', 'kids'::resource_kind, 'A drawing of a backpack the child fills with tools they can use when feelings get big.', 'Use it to help a child picture and remember their own calming tools.', array['Children']::text[], '25 minutes', 'Ask the child to draw a backpack and fill it with things that help, such as breathing, a hug, a song or a squeeze toy. The parent adds one idea and asks when they could use each tool. Hang the drawing where the child can see it.', '[{"id": "f0", "type": "textarea", "label": "Draw your backpack:"}, {"id": "f1", "type": "textarea", "label": "Put three helpers inside:"}, {"id": "f2", "type": "textarea", "label": "When a big feeling comes, what helps:"}, {"id": "f3", "type": "textarea", "label": "Who can help carry it:"}, {"id": "f4", "type": "textarea", "label": "What parent will remind you about:"}]'::jsonb, array['children', 'coping skills', 'art']::text[], '2026-11-08T15:00:00+00:00'::timestamptz),
  ('worry-monster-feeding-box-build', 'Worry Monster Feeding Box Build', 'kids'::resource_kind, 'A box the child decorates as a worry monster that eats the worries they write or draw.', 'Use it to help a child put worries somewhere outside their head.', array['Children']::text[], '30 minutes', 'The child decorates a box with a mouth, then writes or draws a worry and feeds it in. A parent opens it with the child at a set time to talk about any that need help. Never use it to dismiss a worry; some need action.', '[{"id": "f0", "type": "textarea", "label": "Draw your worry monster:"}, {"id": "f1", "type": "textarea", "label": "A worry you fed to it today:"}, {"id": "f2", "type": "textarea", "label": "How you felt after:"}, {"id": "f3", "type": "textarea", "label": "A worry we need to talk about together:"}, {"id": "f4", "type": "textarea", "label": "What parent does when you feed it:"}]'::jsonb, array['children', 'worry', 'play']::text[], '2026-11-08T15:00:00+00:00'::timestamptz),
  ('kindness-chain-paper-links-activity', 'Kindness Chain Paper Links Activity', 'kids'::resource_kind, 'A paper chain where each link records a kind thing the child did or noticed.', 'Use it to help a child notice and build on small acts of kindness.', array['Children']::text[], '20 minutes plus a week', 'Cut strips of paper and have the child add a link each time they do or see something kind, writing or drawing on it. The parent joins in and adds links too. Watch the chain grow and talk about how each link felt.', '[{"id": "f0", "type": "textarea", "label": "A kind thing I did:"}, {"id": "f1", "type": "textarea", "label": "A kind thing someone did for me:"}, {"id": "f2", "type": "textarea", "label": "How it felt:"}, {"id": "f3", "type": "textarea", "label": "Who I want to be kind to next:"}, {"id": "f4", "type": "textarea", "label": "What parent does to help add links:"}]'::jsonb, array['children', 'kindness', 'craft']::text[], '2026-11-08T15:00:00+00:00'::timestamptz),
  ('safe-place-imagination-painting', 'Safe Place Imagination Painting', 'kids'::resource_kind, 'A painting of an imagined safe place with the sights, sounds and people the child chooses.', 'Use it to help a child build a calm place in their imagination to visit when upset.', array['Children']::text[], '30 minutes', 'Invite the child to paint a place where they feel calm and safe, real or imagined, adding colors, sounds and who is there. Let them keep it theirs and keep the questions light. A parent practices visiting it with the child for a minute. If a child discloses something worrying, follow your reporting duties.', '[{"id": "f0", "type": "textarea", "label": "Paint your safe place:"}, {"id": "f1", "type": "textarea", "label": "What you see there:"}, {"id": "f2", "type": "textarea", "label": "What you hear and smell there:"}, {"id": "f3", "type": "textarea", "label": "Who or what is with you:"}, {"id": "f4", "type": "textarea", "label": "When you might visit it:"}]'::jsonb, array['children', 'safety', 'grounding']::text[], '2026-11-08T15:00:00+00:00'::timestamptz),
  ('act-the-feeling-guessing-group-game', 'Act the Feeling Guessing Group Game', 'game'::resource_kind, 'A group game of acting out feelings for others to guess, followed by a short debrief.', 'Use it to help a group put names to feelings and notice how they look from outside.', array['Groups', 'Children', 'Teens']::text[], '30 minutes', 'Players take turns drawing a feeling card and acting it without words while others guess. After a few rounds, ask what clues gave it away and when they have felt it. Keep the tone silly and let anyone pass without comment.', '[{"id": "f0", "type": "textarea", "label": "The feeling I acted out:"}, {"id": "f1", "type": "textarea", "label": "How others guessed it:"}, {"id": "f2", "type": "textarea", "label": "A time I felt it:"}, {"id": "f3", "type": "textarea", "label": "What I notice about how feelings show:"}, {"id": "f4", "type": "textarea", "label": "Something I learned from the group:"}]'::jsonb, array['group', 'emotion identification', 'play']::text[], '2026-11-08T15:00:00+00:00'::timestamptz),
  ('strengths-spotlight-round-robin-game', 'Strengths Spotlight Round Robin Game', 'game'::resource_kind, 'A circle game where each player is given a strength by the group.', 'Use it to help a group name and receive each other''s strengths.', array['Groups', 'Teens', 'Adults']::text[], '30 minutes', 'Each player takes a turn in the spotlight while others offer one strength they have seen, and the player notes what rings true. Set a rule that comments are about character and actions, never looks. Close by asking how it felt to receive.', '[{"id": "f0", "type": "textarea", "label": "My strength the group named:"}, {"id": "f1", "type": "textarea", "label": "Which one surprised me:"}, {"id": "f2", "type": "textarea", "label": "Which one I want to use more:"}, {"id": "f3", "type": "textarea", "label": "A strength I saw in someone else:"}, {"id": "f4", "type": "textarea", "label": "How receiving felt:"}]'::jsonb, array['group', 'strengths', 'self-esteem']::text[], '2026-11-08T15:00:00+00:00'::timestamptz),
  ('calm-down-breathing-relay-game', 'Calm Down Breathing Relay Game', 'game'::resource_kind, 'A team relay where players pass a calm-breathing task around a circle.', 'Use it to help a group learn and enjoy simple breathing and slow-down skills.', array['Groups', 'Children', 'Teens']::text[], '25 minutes', 'Teams complete a slow-breathing task such as smelling the flower and blowing out the candle, passing a bean bag after each round. Slow wins, not fast. Debrief on which breath felt best and when they could use it.', '[{"id": "f0", "type": "textarea", "label": "The breathing move I liked best:"}, {"id": "f1", "type": "textarea", "label": "How my body felt afterward:"}, {"id": "f2", "type": "textarea", "label": "When I could use it:"}, {"id": "f3", "type": "textarea", "label": "What made it hard to slow down:"}, {"id": "f4", "type": "textarea", "label": "A tip I would give a friend:"}]'::jsonb, array['group', 'coping skills', 'regulation']::text[], '2026-11-08T15:00:00+00:00'::timestamptz),
  ('thought-detective-cards-game', 'Thought Detective Cards Game', 'game'::resource_kind, 'A card game where players find the clue that shows a thought might not be the whole story.', 'Use it to help a group practice looking for facts behind a quick thought.', array['Groups', 'Teens']::text[], '30 minutes', 'Players draw a card with a thought, such as "No one wants to sit with me," and find clues for and against it. Turns rotate; the group offers other explanations. Debrief on how the detective stance changes how it feels.', '[{"id": "f0", "type": "textarea", "label": "The thought on my card:"}, {"id": "f1", "type": "textarea", "label": "A clue that fits it:"}, {"id": "f2", "type": "textarea", "label": "A clue that does not fit it:"}, {"id": "f3", "type": "textarea", "label": "Another explanation that could be true:"}, {"id": "f4", "type": "textarea", "label": "How I feel about it now:"}]'::jsonb, array['group', 'thinking traps', 'core CBT']::text[], '2026-11-08T15:00:00+00:00'::timestamptz),
  ('teamwork-tower-building-challenge', 'Teamwork Tower Building Challenge', 'game'::resource_kind, 'A group building game with turn rules that ends in a talk about cooperation and frustration.', 'Use it to help a group notice how they handle frustration and work together.', array['Groups', 'Children', 'Teens']::text[], '30 minutes', 'Teams build a tower from simple materials with rules like one hand only or no talking for a round. Notice who leads, who steps back, and how frustration shows. In the debrief ask what helped the team and what each player might try next time.', '[{"id": "f0", "type": "textarea", "label": "What I did during the challenge:"}, {"id": "f1", "type": "textarea", "label": "What frustrated me:"}, {"id": "f2", "type": "textarea", "label": "What helped our team:"}, {"id": "f3", "type": "textarea", "label": "What I would do differently:"}, {"id": "f4", "type": "textarea", "label": "What I learned about working together:"}]'::jsonb, array['group', 'communication', 'play']::text[], '2026-11-08T15:00:00+00:00'::timestamptz),
  ('window-of-tolerance-zones-tracker', 'Window of Tolerance Zones Tracker', 'worksheet'::resource_kind, 'A page for marking when a client feels too revved up, steady or shut down across a week.', 'Use it to help a client notice which state they are in and what helps them return to steady.', array['Adults', 'Teens']::text[], '20 minutes, then a week of notes', 'Introduce three zones in plain words and have the client mark where they were at a few points each day. Never ask for what happened; just the state, body cues and what helped. Review for patterns and pick one anchoring step that worked.', '[{"id": "f0", "type": "textarea", "label": "The state I was in today and the time:"}, {"id": "f1", "type": "textarea", "label": "Signs in my body that told me:"}, {"id": "f2", "type": "textarea", "label": "What was going on around me, in a word or two:"}, {"id": "f3", "type": "textarea", "label": "What helped me come back to steady:"}, {"id": "f4", "type": "textarea", "label": "One anchoring step I will keep:"}]'::jsonb, array['PTSD and trauma', 'grounding', 'pacing']::text[], '2026-11-08T15:00:00+00:00'::timestamptz),
  ('safety-versus-danger-present-moment-check', 'Safety Versus Danger Present Moment Check', 'cbt'::resource_kind, 'A thought-check sheet for telling a memory-triggered alarm from danger in the room now.', 'Use it to help a client sort what is happening now from what the alarm is reminding them of.', array['Adults', 'Teens']::text[], '25 minutes', 'Teach the client to ask, "Is this memory or is this now?" and list what in the room shows they are safe today. Keep it in the present and never ask for details of the past event. Rehearse it in session before they use it between visits.', '[{"id": "f0", "type": "textarea", "label": "What set off my alarm today:"}, {"id": "f1", "type": "textarea", "label": "What my body did:"}, {"id": "f2", "type": "textarea", "label": "What I can see and hear that shows I am safe now:"}, {"id": "f3", "type": "textarea", "label": "What the alarm may be reminding me of, in a word:"}, {"id": "f4", "type": "textarea", "label": "What I will do to steady myself:"}, {"id": "f5", "type": "textarea", "label": "If I feel unsafe, I can call or text 988 or my support person:"}]'::jsonb, array['PTSD and trauma', 'safety', 'thinking traps']::text[], '2026-11-08T15:00:00+00:00'::timestamptz),
  ('making-room-for-hard-memories-dial-page', 'Making Room for Hard Memories Dial Page', 'act'::resource_kind, 'A page for practicing a little room for a hard feeling while staying in the present.', 'Use it to help a client practice making a small amount of room for a feeling while staying anchored.', array['Adults', 'Teens']::text[], '20 minutes', 'Keep the client rooted in the room with feet on the floor and eyes open. They notice a mild feeling only, not a memory, and rate how much room they can make. Stay at the low end of intensity and stop whenever they ask. Pacing is the skill.', '[{"id": "f0", "type": "textarea", "label": "A mild feeling I can notice today:"}, {"id": "f1", "type": "textarea", "label": "Where my feet and hands are right now:"}, {"id": "f2", "type": "textarea", "label": "How much room I can make for it, 0 to 10:"}, {"id": "f3", "type": "textarea", "label": "What helps me stay here:"}, {"id": "f4", "type": "textarea", "label": "What matters to me that I can do while it is there:"}]'::jsonb, array['PTSD and trauma', 'acceptance', 'pacing']::text[], '2026-11-08T15:00:00+00:00'::timestamptz),
  ('grounding-with-the-five-senses-skills-card', 'Grounding With the Five Senses Skills Card', 'dbt'::resource_kind, 'A skills card for shifting attention to what the senses can find in the room.', 'Use it to help a client shift into the present when the past pulls on them.', array['Adults', 'Teens']::text[], '15 minutes', 'Practice the five senses card in session while the client is calm so it is familiar before they need it. Let them choose which senses work best, since some find sound or touch easier. Add a temperature or movement option, and keep a copy in a pocket.', '[{"id": "f0", "type": "textarea", "label": "Five things I can see:"}, {"id": "f1", "type": "textarea", "label": "Four things I can touch:"}, {"id": "f2", "type": "textarea", "label": "Three things I can hear:"}, {"id": "f3", "type": "textarea", "label": "The sense that works best for me:"}, {"id": "f4", "type": "textarea", "label": "Where I will keep this card:"}]'::jsonb, array['PTSD and trauma', 'grounding', 'distress tolerance']::text[], '2026-11-08T15:00:00+00:00'::timestamptz),
  ('partner-support-pacing-plan-for-hard-days', 'Partner Support Pacing Plan for Hard Days', 'couples'::resource_kind, 'A plan for a partner to know what helps and what to avoid when the other is having a hard day.', 'Use it to help partners agree on how to support each other when old stress rises.', array['Couples']::text[], '30 minutes', 'The partner who struggles says what helps and what does not, in terms of actions rather than the past. The other writes it down and says it back. Agree on a sign to pause. Details of the past are not part of this, and either person may stop.', '[{"id": "f0", "type": "textarea", "label": "Partner A: What helps me on a hard day:"}, {"id": "f1", "type": "textarea", "label": "Partner A: What does not help:"}, {"id": "f2", "type": "textarea", "label": "Partner B: What I can do to support:"}, {"id": "f3", "type": "textarea", "label": "Our sign that I need a pause:"}, {"id": "f4", "type": "textarea", "label": "What we will do afterward to reconnect:"}]'::jsonb, array['PTSD and trauma', 'support', 'couples']::text[], '2026-11-08T15:00:00+00:00'::timestamptz),
  ('worry-paint-splat-page-for-big-moments', 'Worry Paint-Splat Page for Big Moments', 'kids'::resource_kind, 'A painting where a child splats colors for the energy of a worry and then adds a calm corner.', 'Use it to help a child let out nervous energy through paint and then settle.', array['Children']::text[], '25 minutes', 'Give the child washable paint and paper and invite them to splat or dab how the worry feels, with no rules. Then paint a calm corner, and the parent joins in. Keep the focus on color and feeling.', '[{"id": "f0", "type": "textarea", "label": "Paint how your worry feels:"}, {"id": "f1", "type": "textarea", "label": "Paint a calm corner:"}, {"id": "f2", "type": "textarea", "label": "The colors you chose and why:"}, {"id": "f3", "type": "textarea", "label": "What helped you settle:"}, {"id": "f4", "type": "textarea", "label": "What parent does to help:"}]'::jsonb, array['anxiety', 'children', 'art']::text[], '2026-11-08T15:00:00+00:00'::timestamptz),
  ('worry-wave-surfing-game-for-groups', 'Worry Wave Surfing Game for Groups', 'game'::resource_kind, 'A group game where players ride out pretend waves of worry on a balance cushion and cheer each other.', 'Use it to help a group see that worry rises and falls and can be ridden out.', array['Groups', 'Teens', 'Children']::text[], '25 minutes', 'Players stand on a cushion or line while the leader calls out small worries on a wave that rises and fades. Each player rates their worry and notices it ease. Debrief on what helped them stay on the board.', '[{"id": "f0", "type": "textarea", "label": "My worry on the wave, 0 to 10:"}, {"id": "f1", "type": "textarea", "label": "What I did while it rose:"}, {"id": "f2", "type": "textarea", "label": "What happened as it faded:"}, {"id": "f3", "type": "textarea", "label": "What helped me stay on the board:"}, {"id": "f4", "type": "textarea", "label": "When I could surf a real one:"}]'::jsonb, array['anxiety', 'group', 'play']::text[], '2026-11-08T15:00:00+00:00'::timestamptz),
  ('uncertainty-tolerance-tiny-experiments-list', 'Uncertainty Tolerance Tiny Experiments List', 'worksheet'::resource_kind, 'A list of small experiments where a client acts without certainty and notes what happened.', 'Use it to help a client practice acting without waiting for certainty.', array['Adults', 'Teens']::text[], '30 minutes, then a week', 'List small situations where the client usually seeks reassurance or certainty, ranked from mild to harder. Choose one mild one and do it without checking. Record what happened and what the client noticed about the discomfort.', '[{"id": "f0", "type": "textarea", "label": "A situation where I want to be certain:"}, {"id": "f1", "type": "textarea", "label": "What I usually do to feel sure:"}, {"id": "f2", "type": "textarea", "label": "A small experiment where I go without it:"}, {"id": "f3", "type": "textarea", "label": "What I expected to happen:"}, {"id": "f4", "type": "textarea", "label": "What actually happened:"}]'::jsonb, array['anxiety', 'uncertainty', 'behavioral experiment']::text[], '2026-11-08T15:00:00+00:00'::timestamptz),
  ('what-if-to-what-is-then-thought-chain', 'What If to What Is Then Thought Chain', 'cbt'::resource_kind, 'A chain that turns a what-if worry into the likely and the coping steps that follow.', 'Use it to help a client move from endless what-ifs toward what is likely and what they could do.', array['Adults', 'Teens']::text[], '30 minutes', 'Write the what-if worry, then ask for the most likely outcome, the best case and the worst case, and finally how they would cope with the worst. The coping part is where relief often arrives. Keep the client from adding new what-ifs by asking them to stay with one.', '[{"id": "f0", "type": "textarea", "label": "The what-if worry:"}, {"id": "f1", "type": "textarea", "label": "The most likely outcome:"}, {"id": "f2", "type": "textarea", "label": "The best case:"}, {"id": "f3", "type": "textarea", "label": "The worst case:"}, {"id": "f4", "type": "textarea", "label": "How I would cope if the worst happened:"}, {"id": "f5", "type": "textarea", "label": "What I will say to myself instead:"}]'::jsonb, array['anxiety', 'worry', 'core CBT']::text[], '2026-11-08T15:00:00+00:00'::timestamptz),
  ('anxiety-as-a-background-hum-defusion-page', 'Anxiety as a Background Hum Defusion Page', 'act'::resource_kind, 'A page that treats anxiety as a hum in the background while the client does what matters.', 'Use it to help a client carry anxiety along without letting it run the day.', array['Adults', 'Teens']::text[], '20 minutes', 'Invite the client to picture anxiety as background noise that can be turned down but not off. Then pick a valued action to do with the hum on. Skip any promise that the hum goes away; the point is doing what matters with it present.', '[{"id": "f0", "type": "textarea", "label": "What my anxiety sounds like when it is loud:"}, {"id": "f1", "type": "textarea", "label": "What it tells me to do:"}, {"id": "f2", "type": "textarea", "label": "Something that matters that I can do with it there:"}, {"id": "f3", "type": "textarea", "label": "How I will carry it with me:"}, {"id": "f4", "type": "textarea", "label": "What I noticed afterward:"}]'::jsonb, array['anxiety', 'defusion', 'core ACT']::text[], '2026-11-08T15:00:00+00:00'::timestamptz),
  ('self-soothe-kit-for-low-days-checklist', 'Self-Soothe Kit for Low Days Checklist', 'dbt'::resource_kind, 'A checklist for building a small kit of things that soothe each sense on low-mood days.', 'Use it to help a client gather simple comforts for the days when energy is low.', array['Adults', 'Teens']::text[], '25 minutes', 'Walk through each of the five senses and ask for one comforting item or action the client already has at home. The kit should be low effort and easy to reach. Review what got used and what to swap. Include 988 (call or text) on the card for hard nights.', '[{"id": "f0", "type": "textarea", "label": "Something comforting to see:"}, {"id": "f1", "type": "textarea", "label": "Something comforting to hear:"}, {"id": "f2", "type": "textarea", "label": "Something comforting to touch:"}, {"id": "f3", "type": "textarea", "label": "Something comforting to smell or taste:"}, {"id": "f4", "type": "textarea", "label": "Where I will keep the kit:"}, {"id": "f5", "type": "textarea", "label": "If a night feels unsafe, I can call or text 988:"}]'::jsonb, array['depression', 'self-soothing', 'skills']::text[], '2026-11-08T15:00:00+00:00'::timestamptz),
  ('low-mood-partner-support-menu', 'Low Mood Partner Support Menu', 'couples'::resource_kind, 'A menu where one partner says what kind of support they would like on low days and the other chooses.', 'Use it to help partners talk about how to support each other when mood is low.', array['Couples']::text[], '30 minutes', 'The partner with the low days names what feels supportive, such as company, a walk or quiet, and what feels like pressure. The other picks two to try. Keep it about actions and not blame, and plan a check-in to adjust.', '[{"id": "f0", "type": "textarea", "label": "Partner A: What helps when my mood is low:"}, {"id": "f1", "type": "textarea", "label": "Partner A: What feels like pressure:"}, {"id": "f2", "type": "textarea", "label": "Partner B: Two things I can offer:"}, {"id": "f3", "type": "textarea", "label": "How we will check in on how it is going:"}, {"id": "f4", "type": "textarea", "label": "If things feel unsafe, we can call or text 988:"}]'::jsonb, array['depression', 'support', 'couples']::text[], '2026-11-08T15:00:00+00:00'::timestamptz),
  ('mood-mountain-climbing-picture', 'Mood Mountain Climbing Picture', 'kids'::resource_kind, 'A picture of a mountain with a child''s mood ups and downs marked along the path.', 'Use it to help a child see that moods change and find helpers for the low parts.', array['Children']::text[], '30 minutes', 'Draw a mountain with a path and have the child mark where they feel high and low and what helps them climb. The parent adds a helper at the low points. Keep it light, and if a child says something that worries you, follow your reporting and safety steps.', '[{"id": "f0", "type": "textarea", "label": "Draw your mood mountain:"}, {"id": "f1", "type": "textarea", "label": "Where you are on it today:"}, {"id": "f2", "type": "textarea", "label": "What makes it go up:"}, {"id": "f3", "type": "textarea", "label": "What helps when it goes down:"}, {"id": "f4", "type": "textarea", "label": "Who can help you climb:"}]'::jsonb, array['depression', 'children', 'emotion identification']::text[], '2026-11-08T15:00:00+00:00'::timestamptz),
  ('tiny-wins-jar-group-game', 'Tiny Wins Jar Group Game', 'game'::resource_kind, 'A group game where each player adds small wins to a shared jar and draws one to read aloud.', 'Use it to help a group notice small things done on low-energy days.', array['Groups', 'Teens', 'Adults']::text[], '25 minutes', 'Each player writes small wins from the week on slips, such as getting out of bed or sending a text, and the jar is passed around. Players draw one to read aloud without naming who wrote it. Debrief on what counts as a win.', '[{"id": "f0", "type": "textarea", "label": "A small win of mine this week:"}, {"id": "f1", "type": "textarea", "label": "A win I heard that I liked:"}, {"id": "f2", "type": "textarea", "label": "What counts as a win on a low day:"}, {"id": "f3", "type": "textarea", "label": "What I want to add to the jar next:"}, {"id": "f4", "type": "textarea", "label": "How this felt:"}]'::jsonb, array['depression', 'group', 'strengths']::text[], '2026-11-08T15:00:00+00:00'::timestamptz),
  ('small-steps-activity-ladder', 'Small Steps Activity Ladder', 'worksheet'::resource_kind, 'A ladder of activities from tiny to bigger that a client climbs one rung at a time on low-mood days.', 'Use it to help a client start with activities that feel doable and build gradually.', array['Adults', 'Teens']::text[], '25 minutes', 'List activities the client once enjoyed or values, then rank them from easiest to hardest. Begin at the lowest rung and expect to stay there for a while. Note mood before and after to see what matters.', '[{"id": "f0", "type": "textarea", "label": "Activities I used to enjoy:"}, {"id": "f1", "type": "textarea", "label": "Activities I value:"}, {"id": "f2", "type": "textarea", "label": "My easiest rung:"}, {"id": "f3", "type": "textarea", "label": "My next rung:"}, {"id": "f4", "type": "textarea", "label": "Mood before and after, 0 to 10:"}]'::jsonb, array['depression', 'behavioral activation', 'planning']::text[], '2026-11-08T15:00:00+00:00'::timestamptz),
  ('task-start-timer-and-five-minute-rule-log', 'Task Start Timer and Five Minute Rule Log', 'cbt'::resource_kind, 'A log for starting a task with a short timer and noting what happened.', 'Use it to help a client get moving on a task with a short, bounded start.', array['Adults', 'Teens']::text[], 'Two weeks of daily entries', 'The client picks a task, sets a five minute timer and notes what happened. They may stop when the timer ends, which lowers the barrier; many keep going. Review what makes starting hard and which tasks respond to this.', '[{"id": "f0", "type": "textarea", "label": "The task I want to start:"}, {"id": "f1", "type": "textarea", "label": "What makes it hard to start:"}, {"id": "f2", "type": "textarea", "label": "How long I set the timer for:"}, {"id": "f3", "type": "textarea", "label": "What happened:"}, {"id": "f4", "type": "textarea", "label": "What I will try next time:"}]'::jsonb, array['ADHD', 'habits', 'planning']::text[], '2026-11-08T15:00:00+00:00'::timestamptz),
  ('values-focus-compass-for-wandering-attention', 'Values Focus Compass for Wandering Attention', 'act'::resource_kind, 'A compass page for noticing when attention drifts and steering back to what matters.', 'Use it to help a client return attention to a valued task kindly after it wanders.', array['Adults', 'Teens']::text[], '20 minutes', 'Name what the client wants to do with their attention today and how it tends to get pulled. Practice noticing the drift and returning without scolding. Keep the compass simple so it can fit on a sticky note.', '[{"id": "f0", "type": "textarea", "label": "What I want to put my attention on today:"}, {"id": "f1", "type": "textarea", "label": "What usually pulls it away:"}, {"id": "f2", "type": "textarea", "label": "How I notice it has drifted:"}, {"id": "f3", "type": "textarea", "label": "How I come back kindly:"}, {"id": "f4", "type": "textarea", "label": "Why it matters to me:"}]'::jsonb, array['ADHD', 'values', 'mindfulness']::text[], '2026-11-08T15:00:00+00:00'::timestamptz),
  ('impulse-pause-wise-choice-card', 'Impulse Pause Wise Choice Card', 'dbt'::resource_kind, 'A card for pausing before acting on a quick impulse and picking a wiser next step.', 'Use it to help a client create a short gap between impulse and action.', array['Adults', 'Teens']::text[], '20 minutes', 'The client names the impulses that cause trouble and picks a pause move such as counting breaths or a hand on the chest. Practice one in session. Aim for a short gap, not perfect control, and celebrate each pause.', '[{"id": "f0", "type": "textarea", "label": "An impulse that gets me into trouble:"}, {"id": "f1", "type": "textarea", "label": "What it feels like in my body right before:"}, {"id": "f2", "type": "textarea", "label": "My pause move:"}, {"id": "f3", "type": "textarea", "label": "What a wiser choice could be:"}, {"id": "f4", "type": "textarea", "label": "How I will remember the card:"}]'::jsonb, array['ADHD', 'regulation', 'skills']::text[], '2026-11-08T15:00:00+00:00'::timestamptz),
  ('household-roles-and-reminders-fair-share-planner', 'Household Roles and Reminders Fair Share Planner', 'couples'::resource_kind, 'A planner for partners to talk about who tracks what and how to remind each other without nagging.', 'Use it to help partners share the mental load and agree on kind reminders.', array['Couples']::text[], '35 minutes', 'Partners list recurring tasks and who notices, plans and does each. Talk about what reminders feel supportive and what feels like criticism. Choose a shared system such as a calendar or a note and review it weekly.', '[{"id": "f0", "type": "textarea", "label": "Tasks that cause friction:"}, {"id": "f1", "type": "textarea", "label": "Partner A: Which I notice and which I do:"}, {"id": "f2", "type": "textarea", "label": "Partner B: Which I notice and which I do:"}, {"id": "f3", "type": "textarea", "label": "A reminder style that helps us:"}, {"id": "f4", "type": "textarea", "label": "Our shared system and who sets it up:"}]'::jsonb, array['ADHD', 'relationship issues', 'planning']::text[], '2026-11-08T15:00:00+00:00'::timestamptz),
  ('brain-busy-body-movement-break-chart', 'Brain Busy Body Movement Break Chart', 'kids'::resource_kind, 'A chart a child decorates with movement breaks they pick for when focus gets slippery.', 'Use it to help a child have a set of movement breaks ready for restless moments.', array['Children']::text[], '25 minutes', 'The child draws and chooses five movement breaks, such as wall push-ups or jumping jacks, and a parent places the chart where homework happens. Make the breaks short and fun. Praise using the break and not just finishing the task.', '[{"id": "f0", "type": "textarea", "label": "Draw your five movement breaks:"}, {"id": "f1", "type": "textarea", "label": "When you will use them:"}, {"id": "f2", "type": "textarea", "label": "How your body feels after one:"}, {"id": "f3", "type": "textarea", "label": "What helps you get back to work:"}, {"id": "f4", "type": "textarea", "label": "What parent does when you need a break:"}]'::jsonb, array['ADHD', 'children', 'routines']::text[], '2026-11-08T15:00:00+00:00'::timestamptz),
  ('urge-wave-lifeguard-group-game', 'Urge Wave Lifeguard Group Game', 'game'::resource_kind, 'A group game where players ride a pretend wave of urge and track it rising and falling.', 'Use it to help a group see that urges peak and pass without acting on them.', array['Groups', 'Adults', 'Teens']::text[], '25 minutes', 'Players call out an urge level from 0 to 10 as the leader reads a short wave story. Debrief on what changed as the wave passed and what helped them hold on. Keep it about substance use urges generally and never ask for personal detail.', '[{"id": "f0", "type": "textarea", "label": "The urge level at its peak:"}, {"id": "f1", "type": "textarea", "label": "What helped me ride it:"}, {"id": "f2", "type": "textarea", "label": "What happened as it passed:"}, {"id": "f3", "type": "textarea", "label": "A place I might use this skill:"}, {"id": "f4", "type": "textarea", "label": "What I want to remember:"}]'::jsonb, array['addiction', 'urges', 'group']::text[], '2026-11-08T15:00:00+00:00'::timestamptz),
  ('triggers-people-places-moods-map', 'Triggers People Places Moods Map', 'worksheet'::resource_kind, 'A map of the people, places and moods that stir urges for substance use.', 'Use it to help a client see what tends to come before an urge and plan around it.', array['Adults', 'Teens']::text[], '30 minutes', 'Draw three columns and have the client fill in what comes before urges: people, places and moods. Look together for patterns and for one trigger they can plan for. Keep it factual and without blame.', '[{"id": "f0", "type": "textarea", "label": "People that stir urges:"}, {"id": "f1", "type": "textarea", "label": "Places that stir urges:"}, {"id": "f2", "type": "textarea", "label": "Moods that stir urges:"}, {"id": "f3", "type": "textarea", "label": "The trigger I will plan for first:"}, {"id": "f4", "type": "textarea", "label": "What I will do instead:"}]'::jsonb, array['addiction', 'triggers', 'substance use']::text[], '2026-11-08T15:00:00+00:00'::timestamptz),
  ('urge-thoughts-and-permission-statements-sheet', 'Urge Thoughts and Permission Statements Sheet', 'cbt'::resource_kind, 'A sheet for spotting thoughts that give permission for substance use and answering them.', 'Use it to help a client notice the permission-giving thoughts that come before use.', array['Adults', 'Teens']::text[], '30 minutes', 'Teach the client to spot thoughts like "one won''t hurt" and write a response. Make the answers short and in the client''s own voice so they can recall them in the moment. Rehearse the answers aloud.', '[{"id": "f0", "type": "textarea", "label": "A thought that gives permission:"}, {"id": "f1", "type": "textarea", "label": "What it leads me to do:"}, {"id": "f2", "type": "textarea", "label": "A short answer that is true for me:"}, {"id": "f3", "type": "textarea", "label": "What I want my life to look like:"}, {"id": "f4", "type": "textarea", "label": "Who I can contact when the thought is loud:"}]'::jsonb, array['addiction', 'automatic thoughts', 'substance use']::text[], '2026-11-08T15:00:00+00:00'::timestamptz),
  ('values-behind-the-urge-page', 'Values Behind the Urge Page', 'act'::resource_kind, 'A page that looks at what the client is seeking when an urge arises and other routes to it.', 'Use it to help a client find what they need under an urge and other ways to meet it.', array['Adults', 'Teens']::text[], '25 minutes', 'Ask what the urge promises, such as ease or company, and what value sits near it. Explore other routes to that need. The aim is a range of choices, so avoid judging past use.', '[{"id": "f0", "type": "textarea", "label": "What the urge promises me:"}, {"id": "f1", "type": "textarea", "label": "What I need underneath it:"}, {"id": "f2", "type": "textarea", "label": "What I care about that is near it:"}, {"id": "f3", "type": "textarea", "label": "Another way to meet the need:"}, {"id": "f4", "type": "textarea", "label": "One step I will take:"}]'::jsonb, array['addiction', 'values', 'urges']::text[], '2026-11-08T15:00:00+00:00'::timestamptz),
  ('crisis-survival-plan-for-urges-card', 'Crisis Survival Plan for Urges Card', 'dbt'::resource_kind, 'A card with distress-tolerance skills to try, in order, when an urge feels too strong.', 'Use it to help a client have a short ordered list of skills when an urge peaks.', array['Adults', 'Teens']::text[], '25 minutes', 'Build the card with the client: temperature change, paced breathing, a short walk, a call. Practice one in session. Include a contact and 988 (call or text) if the urge comes with thoughts of self-harm. Revisit and revise.', '[{"id": "f0", "type": "textarea", "label": "My first skill when an urge peaks:"}, {"id": "f1", "type": "textarea", "label": "My second skill:"}, {"id": "f2", "type": "textarea", "label": "A person I can call:"}, {"id": "f3", "type": "textarea", "label": "A place I can go that helps:"}, {"id": "f4", "type": "textarea", "label": "If I feel unsafe, I can call or text 988:"}]'::jsonb, array['addiction', 'distress tolerance', 'safety']::text[], '2026-11-08T15:00:00+00:00'::timestamptz),
  ('heat-of-the-moment-time-out-agreement', 'Heat of the Moment Time-Out Agreement', 'couples'::resource_kind, 'A written agreement partners make for stepping away from anger and coming back to talk.', 'Use it to help partners agree on a way to pause anger and return to the talk.', array['Couples']::text[], '30 minutes', 'Partners agree on a signal, a length of break, what each does in the break and how they return. The person who calls the break owns the return. Practice it in a mild moment first. If there is any fear for safety in the relationship, address that separately.', '[{"id": "f0", "type": "textarea", "label": "Our signal for a time-out:"}, {"id": "f1", "type": "textarea", "label": "How long we will take, and what we do:"}, {"id": "f2", "type": "textarea", "label": "Who comes back, and when:"}, {"id": "f3", "type": "textarea", "label": "Partner A: What helps me cool down:"}, {"id": "f4", "type": "textarea", "label": "Partner B: What helps me cool down:"}]'::jsonb, array['anger management', 'conflict', 'couples']::text[], '2026-11-08T15:00:00+00:00'::timestamptz),
  ('volcano-cooling-down-craft', 'Volcano Cooling Down Craft', 'kids'::resource_kind, 'A craft where a child builds a volcano and chooses cool-down moves for when anger builds.', 'Use it to help a child notice anger building and pick a calm-down move early.', array['Children']::text[], '30 minutes', 'Build a volcano from paper or clay and mark levels from calm to erupting. The child chooses a cool-down move for each level. The parent practices with them and models using one. Say that anger is okay and hurting others is not.', '[{"id": "f0", "type": "textarea", "label": "Draw or build your volcano:"}, {"id": "f1", "type": "textarea", "label": "What it feels like at the middle level:"}, {"id": "f2", "type": "textarea", "label": "My cool-down moves:"}, {"id": "f3", "type": "textarea", "label": "What I can do before it erupts:"}, {"id": "f4", "type": "textarea", "label": "What parent does to help:"}]'::jsonb, array['anger management', 'children', 'craft']::text[], '2026-11-08T15:00:00+00:00'::timestamptz),
  ('anger-level-mime-game', 'Anger Level Mime Game', 'game'::resource_kind, 'A group game of showing anger at different levels without words and naming a cool-down move.', 'Use it to help a group tell the levels of anger apart and practice early cool-downs.', array['Groups', 'Children', 'Teens']::text[], '30 minutes', 'Players act a level from 1 to 10 for others to guess and then name a cool-down move for it. Keep it silly and include no real conflicts. Debrief on the early signs and the moves that fit each level.', '[{"id": "f0", "type": "textarea", "label": "The level I acted out:"}, {"id": "f1", "type": "textarea", "label": "How I knew it was that level:"}, {"id": "f2", "type": "textarea", "label": "A cool-down move for that level:"}, {"id": "f3", "type": "textarea", "label": "What my body does at a high level:"}, {"id": "f4", "type": "textarea", "label": "What I will try this week:"}]'::jsonb, array['anger management', 'group', 'regulation']::text[], '2026-11-08T15:00:00+00:00'::timestamptz),
  ('anger-iceberg-under-the-surface-page', 'Anger Iceberg Under the Surface Page', 'worksheet'::resource_kind, 'A page that looks under anger for hurt, fear, shame or tiredness.', 'Use it to help a client find the feelings underneath anger.', array['Adults', 'Teens']::text[], '25 minutes', 'Draw an iceberg with anger at the tip and fill the part below with softer feelings. Ask what the anger is protecting. Not every client finds something; that is fine. Follow with how to say the lower feeling to a safe person.', '[{"id": "f0", "type": "textarea", "label": "The situation that made me angry:"}, {"id": "f1", "type": "textarea", "label": "What the anger looked like:"}, {"id": "f2", "type": "textarea", "label": "What feelings sat under it:"}, {"id": "f3", "type": "textarea", "label": "What the anger was trying to protect:"}, {"id": "f4", "type": "textarea", "label": "How I might say the underneath feeling:"}]'::jsonb, array['anger management', 'emotion identification', 'regulation']::text[], '2026-11-08T15:00:00+00:00'::timestamptz),
  ('hot-thoughts-and-cooler-thoughts-anger-record', 'Hot Thoughts and Cooler Thoughts Anger Record', 'cbt'::resource_kind, 'A record that pairs an angry thought with a cooler thought and notes the shift in feeling.', 'Use it to help a client slow down the thoughts that make anger hotter.', array['Adults', 'Teens']::text[], '30 minutes', 'Pick a recent flare and have the client write the thought that fueled it, rate anger, then write a cooler version that is still true. Avoid asking them to deny the anger. The cooler thought leaves room for the anger and a calm response.', '[{"id": "f0", "type": "textarea", "label": "What happened:"}, {"id": "f1", "type": "textarea", "label": "My hot thought:"}, {"id": "f2", "type": "textarea", "label": "Anger level, 0 to 10:"}, {"id": "f3", "type": "textarea", "label": "A cooler thought that is still true:"}, {"id": "f4", "type": "textarea", "label": "Anger level after:"}, {"id": "f5", "type": "textarea", "label": "What I will do next:"}]'::jsonb, array['anger management', 'thought record', 'core CBT']::text[], '2026-11-08T15:00:00+00:00'::timestamptz),
  ('intrusive-thought-visitor-welcome-page', 'Intrusive Thought Visitor Welcome Page', 'act'::resource_kind, 'A page for noticing an unwanted thought as a visitor that does not need to be obeyed or argued with.', 'Use it to help a client change how they relate to unwanted thoughts, not their content.', array['Adults', 'Teens']::text[], '25 minutes', 'Invite the client to name an intrusive thought as "a thought that showed up" and to notice what they feel pulled to do. Practice letting it stay while doing something valued. Do not ask for reassurance on the thought''s meaning; the page works on the relationship to it.', '[{"id": "f0", "type": "textarea", "label": "An unwanted thought that shows up:"}, {"id": "f1", "type": "textarea", "label": "What I feel pulled to do about it:"}, {"id": "f2", "type": "textarea", "label": "What happens when I give in to that pull:"}, {"id": "f3", "type": "textarea", "label": "What I could do while the thought stays:"}, {"id": "f4", "type": "textarea", "label": "Something I value that I can do today:"}]'::jsonb, array['OCD', 'defusion', 'intrusive thoughts']::text[], '2026-11-08T15:00:00+00:00'::timestamptz),
  ('urge-to-check-delay-and-distract-card', 'Urge to Check Delay and Distract Card', 'dbt'::resource_kind, 'A card for delaying a checking or ritual urge by a few minutes and using a skill meanwhile.', 'Use it to help a client lengthen the gap before acting on a ritual urge.', array['Adults', 'Teens']::text[], '20 minutes', 'The client names a ritual they feel pulled to do, picks a short delay and a skill to use during it. Start with a delay they can manage, such as two minutes. Each stretch of waiting counts. Review what they noticed as the urge moved.', '[{"id": "f0", "type": "textarea", "label": "The ritual I feel pulled to do:"}, {"id": "f1", "type": "textarea", "label": "How strong the pull is, 0 to 10:"}, {"id": "f2", "type": "textarea", "label": "How long I will wait:"}, {"id": "f3", "type": "textarea", "label": "What I will do while I wait:"}, {"id": "f4", "type": "textarea", "label": "What happened to the pull:"}]'::jsonb, array['OCD', 'urges', 'distress tolerance']::text[], '2026-11-08T15:00:00+00:00'::timestamptz),
  ('reassurance-loop-partner-plan', 'Reassurance Loop Partner Plan', 'couples'::resource_kind, 'A plan for partners to talk about reassurance requests and how to answer them kindly without feeding the loop.', 'Use it to help partners respond to repeated reassurance requests with warmth and without getting stuck.', array['Couples']::text[], '35 minutes', 'The partner who asks says what the questions are like for them and the other says what answering feels like. Agree on a supportive line for when the loop starts, such as acknowledging the worry without answering it again. Do it together and in kindness.', '[{"id": "f0", "type": "textarea", "label": "Partner A: What the asking feels like for me:"}, {"id": "f1", "type": "textarea", "label": "Partner B: What the answering feels like for me:"}, {"id": "f2", "type": "textarea", "label": "A kind line we agree to use:"}, {"id": "f3", "type": "textarea", "label": "What Partner A will try instead:"}, {"id": "f4", "type": "textarea", "label": "How we will check how it is going:"}]'::jsonb, array['OCD', 'support', 'relationship issues']::text[], '2026-11-08T15:00:00+00:00'::timestamptz),
  ('worry-bully-talk-back-comic-strip', 'Worry Bully Talk Back Comic Strip', 'kids'::resource_kind, 'A comic strip where a child draws the OCD-like worry as a bully and writes how to talk back.', 'Use it to help a child separate themselves from a bossy worry and practice a firm reply.', array['Children']::text[], '30 minutes', 'The child draws a worry as a character, gives it a silly name and writes what it says. Then they draw how they answer back. A parent learns the name and practices a kind line in place of reassurance. Keep it playful.', '[{"id": "f0", "type": "textarea", "label": "Draw your worry character and give it a name:"}, {"id": "f1", "type": "textarea", "label": "What it bosses you to do:"}, {"id": "f2", "type": "textarea", "label": "Draw yourself talking back:"}, {"id": "f3", "type": "textarea", "label": "What you say to it:"}, {"id": "f4", "type": "textarea", "label": "What parent says when it shows up:"}]'::jsonb, array['OCD', 'children', 'defusion']::text[], '2026-11-08T15:00:00+00:00'::timestamptz),
  ('rule-breaker-experiment-bingo', 'Rule Breaker Experiment Bingo', 'game'::resource_kind, 'A bingo game where players do small, safe rule-breaking tasks and mark their cards.', 'Use it to help a group practice small steps toward doing things the worry says not to.', array['Groups', 'Teens', 'Adults']::text[], '30 minutes', 'Players have cards of small tasks such as leaving a shoe untied or touching a doorknob, chosen with the clinician beforehand to be safe. They mark the squares they try and share what they noticed. Pace by the player''s readiness and make it clear that passing is fine.', '[{"id": "f0", "type": "textarea", "label": "The square I tried:"}, {"id": "f1", "type": "textarea", "label": "What my worry said:"}, {"id": "f2", "type": "textarea", "label": "What happened:"}, {"id": "f3", "type": "textarea", "label": "How I feel about trying another:"}, {"id": "f4", "type": "textarea", "label": "What I want to tell the group:"}]'::jsonb, array['OCD', 'exposure', 'group']::text[], '2026-11-08T15:00:00+00:00'::timestamptz),
  ('panic-wave-body-signals-map', 'Panic Wave Body Signals Map', 'worksheet'::resource_kind, 'A body outline where a client marks where they feel panic and what each sensation means.', 'Use it to help a client map body sensations in panic and notice they pass.', array['Adults', 'Teens']::text[], '25 minutes', 'Have the client mark body sensations on an outline and rate each. Normalize that these sensations are real and uncomfortable, and talk about how they peak and fade. Check in on medical concerns with the client''s doctor rather than reassuring from the page.', '[{"id": "f0", "type": "textarea", "label": "Where I feel panic in my body:"}, {"id": "f1", "type": "textarea", "label": "The sensation that scares me most:"}, {"id": "f2", "type": "textarea", "label": "What I think it means:"}, {"id": "f3", "type": "textarea", "label": "What happened after it peaked:"}, {"id": "f4", "type": "textarea", "label": "What I want to remember next time:"}]'::jsonb, array['panic attacks', 'self-monitoring', 'psychoeducation']::text[], '2026-11-08T15:00:00+00:00'::timestamptz),
  ('catastrophic-interpretation-alternatives-page', 'Catastrophic Interpretation Alternatives Page', 'cbt'::resource_kind, 'A page for listing frightening interpretations of panic sensations and gentler alternatives.', 'Use it to help a client find other explanations for body sensations that scare them.', array['Adults', 'Teens']::text[], '30 minutes', 'Take one panic sensation and have the client write what it feels like it means, then list other possible explanations. Ask for evidence for each. Rate the belief before and after. Keep medical questions with the client''s doctor.', '[{"id": "f0", "type": "textarea", "label": "The sensation:"}, {"id": "f1", "type": "textarea", "label": "What I fear it means:"}, {"id": "f2", "type": "textarea", "label": "How much I believe that, 0 to 100:"}, {"id": "f3", "type": "textarea", "label": "Other explanations that could fit:"}, {"id": "f4", "type": "textarea", "label": "How much I believe the fear now:"}]'::jsonb, array['panic attacks', 'thinking traps', 'core CBT']::text[], '2026-11-08T15:00:00+00:00'::timestamptz),
  ('willing-to-feel-panic-doorway-page', 'Willing to Feel Panic Doorway Page', 'act'::resource_kind, 'A page about opening to panic sensations while doing what matters.', 'Use it to help a client do valued things with panic sensations along for the ride.', array['Adults', 'Teens']::text[], '25 minutes', 'Ask what panic has made the client stop doing and what they would like back. Practice noticing sensations without fighting them, with breath and feet on the floor. Choose a small step into a place or action they have avoided and talk about how willing they are today.', '[{"id": "f0", "type": "textarea", "label": "Something panic has kept me from:"}, {"id": "f1", "type": "textarea", "label": "Why it matters to me:"}, {"id": "f2", "type": "textarea", "label": "How I fight the feeling now:"}, {"id": "f3", "type": "textarea", "label": "What opening to it could look like:"}, {"id": "f4", "type": "textarea", "label": "A small step I am willing to take:"}]'::jsonb, array['panic attacks', 'willingness', 'avoidance']::text[], '2026-11-08T15:00:00+00:00'::timestamptz),
  ('slow-exhale-and-cool-water-surge-card', 'Slow Exhale and Cool Water Surge Card', 'dbt'::resource_kind, 'A card with paced breathing and cool water steps for when panic sensations climb.', 'Use it to help a client have a quick body-based skill ready for a surge.', array['Adults', 'Teens']::text[], '20 minutes', 'Practice paced breathing with a longer exhale and a cold water or ice step in session so it is familiar. Ask what felt useful. Some clients have a health condition that makes temperature skills unsuitable, so check with them first.', '[{"id": "f0", "type": "textarea", "label": "The breathing count that works for me:"}, {"id": "f1", "type": "textarea", "label": "The cool step I can use:"}, {"id": "f2", "type": "textarea", "label": "Where I will have it ready:"}, {"id": "f3", "type": "textarea", "label": "What I say to myself as it climbs:"}, {"id": "f4", "type": "textarea", "label": "How I felt afterward:"}]'::jsonb, array['panic attacks', 'distress tolerance', 'skills']::text[], '2026-11-08T15:00:00+00:00'::timestamptz),
  ('when-panic-hits-partner-coach-card', 'When Panic Hits Partner Coach Card', 'couples'::resource_kind, 'A card for a partner to know how to be present when panic hits, as the person asks.', 'Use it to help partners agree on what support looks like during a panic wave.', array['Couples']::text[], '30 minutes', 'The partner who has panic says what helps in the moment, such as a calm voice or space, and what makes it worse. The other writes it as a short card. Rehearse a calm scene together. Remind them it passes, and that the card can change.', '[{"id": "f0", "type": "textarea", "label": "Partner A: What helps me in a wave:"}, {"id": "f1", "type": "textarea", "label": "Partner A: What does not help:"}, {"id": "f2", "type": "textarea", "label": "Partner B: What I will say and do:"}, {"id": "f3", "type": "textarea", "label": "What we will do after it passes:"}, {"id": "f4", "type": "textarea", "label": "How we will adjust the card:"}]'::jsonb, array['panic attacks', 'support', 'couples']::text[], '2026-11-08T15:00:00+00:00'::timestamptz),
  ('calm-parent-script-role-play-cards', 'Calm Parent Script Role Play Cards', 'kids'::resource_kind, 'Cards a parent and clinician use to rehearse calm replies to a child''s big feelings.', 'Use it to help a parent practice a steady response in the heat of a tough moment.', array['Adults']::text[], '30 minutes', 'Write short scenes such as a meltdown in a store and rehearse a calm reply, with the clinician playing the child. Focus on tone, brevity and naming the feeling. Practice makes the script available when the parent is stressed.', '[{"id": "f0", "type": "textarea", "label": "A scene that tests me:"}, {"id": "f1", "type": "textarea", "label": "What I usually say and do:"}, {"id": "f2", "type": "textarea", "label": "A calm line I would like to use:"}, {"id": "f3", "type": "textarea", "label": "How my voice and body will help:"}, {"id": "f4", "type": "textarea", "label": "What I will try this week:"}]'::jsonb, array['parenting', 'communication', 'skills']::text[], '2026-11-08T15:00:00+00:00'::timestamptz),
  ('family-rules-and-rewards-planning-game', 'Family Rules and Rewards Planning Game', 'game'::resource_kind, 'A family game of drawing cards to agree on household rules, routines and rewards.', 'Use it to help a family build agreed expectations in a fun and fair way.', array['Groups', 'Adults', 'Children']::text[], '35 minutes', 'Family members draw cards such as bedtime, chores and screen time and talk about a fair rule. Each person has a say. Debrief on which rule felt easy and which needs work, and post agreed ones where all can see.', '[{"id": "f0", "type": "textarea", "label": "A rule I think is fair:"}, {"id": "f1", "type": "textarea", "label": "A rule I want to change:"}, {"id": "f2", "type": "textarea", "label": "What would help me follow it:"}, {"id": "f3", "type": "textarea", "label": "How we will celebrate when it works:"}, {"id": "f4", "type": "textarea", "label": "What we will review next week:"}]'::jsonb, array['parenting', 'family', 'routines']::text[], '2026-11-08T15:00:00+00:00'::timestamptz),
  ('praise-that-fits-specific-feedback-log', 'Praise That Fits Specific Feedback Log', 'worksheet'::resource_kind, 'A log for parents to catch specific behavior to praise during the week.', 'Use it to help a parent notice and describe what they like in their child''s behavior.', array['Adults']::text[], 'Daily for one week', 'The parent jots down one specific behavior to praise each day and what they said. Specific praise names what the child did, not what they are. Review which lines landed and what changed. Keep it about actions and warmth.', '[{"id": "f0", "type": "textarea", "label": "Something my child did that I liked:"}, {"id": "f1", "type": "textarea", "label": "What I said, using their action:"}, {"id": "f2", "type": "textarea", "label": "How they responded:"}, {"id": "f3", "type": "textarea", "label": "What I notice about our day:"}, {"id": "f4", "type": "textarea", "label": "A behavior I will look for tomorrow:"}]'::jsonb, array['parenting', 'strengths', 'communication']::text[], '2026-11-08T15:00:00+00:00'::timestamptz),
  ('parent-thought-check-under-pressure-sheet', 'Parent Thought Check Under Pressure Sheet', 'cbt'::resource_kind, 'A thought check for the harsh thoughts a parent has about themselves or their child in hard moments.', 'Use it to help a parent notice and rework thoughts that fuel reactions.', array['Adults']::text[], '30 minutes', 'After a hard moment, the parent writes what they thought, such as "I am failing," and how it pushed them. Work toward a fairer thought and the action it would support. This is about the parent''s inner talk, not about judging how they parent.', '[{"id": "f0", "type": "textarea", "label": "The hard moment:"}, {"id": "f1", "type": "textarea", "label": "What I thought:"}, {"id": "f2", "type": "textarea", "label": "How that thought made me feel and act:"}, {"id": "f3", "type": "textarea", "label": "A fairer thought:"}, {"id": "f4", "type": "textarea", "label": "What I will do next time:"}]'::jsonb, array['parenting', 'automatic thoughts', 'self-compassion']::text[], '2026-11-08T15:00:00+00:00'::timestamptz),
  ('parent-i-want-to-be-daily-moments-page', 'Parent I Want to Be Daily Moments Page', 'act'::resource_kind, 'A page for naming what kind of parent someone wants to be and small daily moments that show it.', 'Use it to help a parent link their values to small ordinary moments.', array['Adults']::text[], '25 minutes', 'Ask what qualities the parent wants their child to feel around them and which small moments show it. Plan one moment each day. Include what gets in the way and how to be kind to themselves when it does.', '[{"id": "f0", "type": "textarea", "label": "The kind of parent I want to be:"}, {"id": "f1", "type": "textarea", "label": "What my child feels around me when I am at my best:"}, {"id": "f2", "type": "textarea", "label": "A daily moment that shows it:"}, {"id": "f3", "type": "textarea", "label": "What gets in the way:"}, {"id": "f4", "type": "textarea", "label": "What I will say to myself when I miss:"}]'::jsonb, array['parenting', 'values', 'committed action']::text[], '2026-11-08T15:00:00+00:00'::timestamptz),
  ('postpartum-night-coping-skills-card', 'Postpartum Night Coping Skills Card', 'dbt'::resource_kind, 'A card of coping skills for hard nights with a new baby, including who to call.', 'Use it to help a new parent have skills and contacts at hand on hard nights.', array['Adults']::text[], '20 minutes', 'Build the card with the parent: breathing, a cold cloth, a trusted person to call, a way to hand off the baby for a short rest. Include 988 (call or text) and the parent''s own provider for thoughts of harm. Complete the card in session.', '[{"id": "f0", "type": "textarea", "label": "A skill that helps me at night:"}, {"id": "f1", "type": "textarea", "label": "A person I can call:"}, {"id": "f2", "type": "textarea", "label": "A way to get a short rest:"}, {"id": "f3", "type": "textarea", "label": "What I say to myself:"}, {"id": "f4", "type": "textarea", "label": "If I have thoughts of harming myself or my baby, I will call or text 988 or my provider:"}]'::jsonb, array['perinatal and postpartum', 'distress tolerance', 'safety']::text[], '2026-11-08T15:00:00+00:00'::timestamptz),
  ('sharing-the-night-shift-partner-plan', 'Sharing the Night Shift Partner Plan', 'couples'::resource_kind, 'A plan for partners to divide nighttime and daytime care and protect each other''s rest.', 'Use it to help partners share care and rest fairly after a baby arrives.', array['Couples']::text[], '35 minutes', 'Partners list the care tasks of day and night and who covers each, and where rest can be protected for each. Keep it flexible, since infants change fast. Check in on resentment and appreciation, and review the plan every week or two.', '[{"id": "f0", "type": "textarea", "label": "Care tasks we each handle now:"}, {"id": "f1", "type": "textarea", "label": "Partner A: When I most need rest:"}, {"id": "f2", "type": "textarea", "label": "Partner B: When I most need rest:"}, {"id": "f3", "type": "textarea", "label": "A plan for the next week:"}, {"id": "f4", "type": "textarea", "label": "Something we appreciate about each other:"}]'::jsonb, array['perinatal and postpartum', 'support', 'couples']::text[], '2026-11-08T15:00:00+00:00'::timestamptz),
  ('welcoming-a-new-baby-sibling-memory-book', 'Welcoming a New Baby Sibling Memory Book', 'kids'::resource_kind, 'A small book a child makes to find their place in the family and mark what stays the same.', 'Use it to help an older child adjust to a new baby with a book of their own.', array['Children']::text[], '30 minutes', 'The child draws pages such as "things I do with my parent" and "what I can teach the baby," while the parent sets aside one-on-one time each day. Name mixed feelings as normal. Keep it honest and kind.', '[{"id": "f0", "type": "textarea", "label": "Draw something we do together:"}, {"id": "f1", "type": "textarea", "label": "What I can teach the baby:"}, {"id": "f2", "type": "textarea", "label": "A feeling I have about the baby:"}, {"id": "f3", "type": "textarea", "label": "What stays the same:"}, {"id": "f4", "type": "textarea", "label": "What parent will do just with me:"}]'::jsonb, array['perinatal and postpartum', 'children', 'family']::text[], '2026-11-08T15:00:00+00:00'::timestamptz),
  ('new-parent-support-group-icebreaker-cards', 'New Parent Support Group Icebreaker Cards', 'game'::resource_kind, 'A card game that gets a group of new parents sharing the real and funny parts of the early weeks.', 'Use it to help new parents connect and feel less alone.', array['Groups', 'Adults']::text[], '35 minutes', 'Parents draw cards like "the weirdest thing I did at 3 a.m." and answer in turn. The leader sets a warm, nonjudgmental tone, with the right to pass. Debrief on what stood out and what support they want from each other.', '[{"id": "f0", "type": "textarea", "label": "A card I answered:"}, {"id": "f1", "type": "textarea", "label": "Something that surprised me:"}, {"id": "f2", "type": "textarea", "label": "Something that helped me this week:"}, {"id": "f3", "type": "textarea", "label": "What I want from this group:"}, {"id": "f4", "type": "textarea", "label": "Who I will reach out to:"}]'::jsonb, array['perinatal and postpartum', 'group', 'connection']::text[], '2026-11-08T15:00:00+00:00'::timestamptz),
  ('care-for-the-caregiver-needs-inventory', 'Care for the Caregiver Needs Inventory', 'worksheet'::resource_kind, 'An inventory of a new parent''s own needs for sleep, food, movement and company, with one small ask.', 'Use it to help a new parent see their own needs and name a small ask.', array['Adults']::text[], '25 minutes', 'Walk down a short list of needs and have the parent rate how well each is met. Choose one need to improve and one person to ask. Normalize that needing help is part of the job.', '[{"id": "f0", "type": "textarea", "label": "Needs that are met:"}, {"id": "f1", "type": "textarea", "label": "Needs that are not:"}, {"id": "f2", "type": "textarea", "label": "One small ask I could make:"}, {"id": "f3", "type": "textarea", "label": "Who I will ask:"}, {"id": "f4", "type": "textarea", "label": "When I will do something just for me:"}]'::jsonb, array['perinatal and postpartum', 'self-care', 'support']::text[], '2026-11-08T15:00:00+00:00'::timestamptz),
  ('inner-critic-fact-check-table', 'Inner Critic Fact Check Table', 'cbt'::resource_kind, 'A table that sets the inner critic''s claims beside facts and a fairer sentence.', 'Use it to help a client check harsh self-judgments against what is actually true.', array['Adults', 'Teens']::text[], '30 minutes', 'List the critic''s claims, then have the client rate belief and find facts that fit or do not. Write a fairer sentence they could say to a friend in the same spot. Keep the client''s own words.', '[{"id": "f0", "type": "textarea", "label": "What my inner critic says:"}, {"id": "f1", "type": "textarea", "label": "How much I believe it, 0 to 100:"}, {"id": "f2", "type": "textarea", "label": "Facts that fit it:"}, {"id": "f3", "type": "textarea", "label": "Facts that do not fit it:"}, {"id": "f4", "type": "textarea", "label": "What I would say to a friend:"}]'::jsonb, array['self-esteem', 'self-criticism', 'thinking traps']::text[], '2026-11-08T15:00:00+00:00'::timestamptz),
  ('self-as-story-rewrite-page', 'Self-as-Story Rewrite Page', 'act'::resource_kind, 'A page for noticing the story a client tells about themselves and choosing what to hold lightly.', 'Use it to help a client see a self-story as a story and hold it more lightly.', array['Adults', 'Teens']::text[], '25 minutes', 'Ask for the story the client tells about who they are, then what experiences it leaves out. Practice saying "I am having the story that..." Explore what a fuller story could include. The point is flexibility, not a positive spin.', '[{"id": "f0", "type": "textarea", "label": "The story I tell about myself:"}, {"id": "f1", "type": "textarea", "label": "When it shows up most:"}, {"id": "f2", "type": "textarea", "label": "What it leaves out:"}, {"id": "f3", "type": "textarea", "label": "A fuller line I could add:"}, {"id": "f4", "type": "textarea", "label": "An action I would take with the story held lightly:"}]'::jsonb, array['self-esteem', 'defusion', 'core ACT']::text[], '2026-11-08T15:00:00+00:00'::timestamptz),
  ('building-mastery-daily-challenge-card', 'Building Mastery Daily Challenge Card', 'dbt'::resource_kind, 'A card for picking a small skill-building task each day and noting the sense of mastery.', 'Use it to help a client collect small experiences of doing something well.', array['Adults', 'Teens']::text[], 'Five minutes daily for two weeks', 'The client picks one task each day that is a little hard but doable and notes how it felt afterward. Increase difficulty slowly. Review how mastery shows up in their view of themselves.', '[{"id": "f0", "type": "textarea", "label": "Today''s task:"}, {"id": "f1", "type": "textarea", "label": "How hard it was, 0 to 10:"}, {"id": "f2", "type": "textarea", "label": "How I felt after:"}, {"id": "f3", "type": "textarea", "label": "What I did well:"}, {"id": "f4", "type": "textarea", "label": "Tomorrow''s task:"}]'::jsonb, array['self-esteem', 'mastery', 'skills']::text[], '2026-11-08T15:00:00+00:00'::timestamptz),
  ('appreciating-the-real-me-partner-exchange', 'Appreciating the Real Me Partner Exchange', 'couples'::resource_kind, 'An exchange where partners say what they see and appreciate in each other beyond roles or performance.', 'Use it to help partners let each other know what they value in who the other is.', array['Couples']::text[], '30 minutes', 'Each partner shares three things they value that have nothing to do with achievements and receives without deflecting. Notice who finds receiving hard. Close with how it felt to hear it, and keep it warm and specific.', '[{"id": "f0", "type": "textarea", "label": "Partner A: What I value in you:"}, {"id": "f1", "type": "textarea", "label": "Partner B: What I value in you:"}, {"id": "f2", "type": "textarea", "label": "What it was like to hear it:"}, {"id": "f3", "type": "textarea", "label": "A moment that shows it:"}, {"id": "f4", "type": "textarea", "label": "How we will say more of this:"}]'::jsonb, array['self-esteem', 'appreciation', 'couples']::text[], '2026-11-08T15:00:00+00:00'::timestamptz),
  ('all-about-me-poster-collage', 'All About Me Poster Collage', 'kids'::resource_kind, 'A collage a child makes of what they like, what they are good at and who loves them.', 'Use it to help a child see and display their own strengths and people.', array['Children']::text[], '35 minutes', 'Provide magazines, markers and glue. The child fills a poster with favorite things, skills and loved ones. The parent adds one thing they love about their child. Hang it where the child will see it.', '[{"id": "f0", "type": "textarea", "label": "Draw or paste what you like:"}, {"id": "f1", "type": "textarea", "label": "What you are good at:"}, {"id": "f2", "type": "textarea", "label": "Who loves you:"}, {"id": "f3", "type": "textarea", "label": "What makes you you:"}, {"id": "f4", "type": "textarea", "label": "What parent wrote on your poster:"}]'::jsonb, array['self-esteem', 'children', 'strengths']::text[], '2026-11-08T15:00:00+00:00'::timestamptz),
  ('conversation-starter-dice-game', 'Conversation Starter Dice Game', 'game'::resource_kind, 'A group game of rolling dice and answering light questions to practice small talk.', 'Use it to help a group practice starting and keeping a conversation in a low-pressure way.', array['Groups', 'Teens', 'Adults']::text[], '30 minutes', 'Players roll a die and answer the matching question, then ask one back. Turns rotate, with a right to pass. Debrief on what made it easier and what each might try outside the room.', '[{"id": "f0", "type": "textarea", "label": "The question I answered:"}, {"id": "f1", "type": "textarea", "label": "What I asked back:"}, {"id": "f2", "type": "textarea", "label": "What made talking easier:"}, {"id": "f3", "type": "textarea", "label": "What felt hard:"}, {"id": "f4", "type": "textarea", "label": "One conversation I will try this week:"}]'::jsonb, array['social anxiety', 'communication', 'group']::text[], '2026-11-08T15:00:00+00:00'::timestamptz),
  ('spotlight-effect-reality-check-page', 'Spotlight Effect Reality Check Page', 'worksheet'::resource_kind, 'A page comparing how much attention a client expects from others with what they actually notice.', 'Use it to help a client test how much others are really watching them.', array['Adults', 'Teens']::text[], '25 minutes', 'Ask the client to rate how much others noticed their worry before a social event, then compare with what they saw others doing. Include a quick look at how much they notice others'' small slips. Keep the tone curious.', '[{"id": "f0", "type": "textarea", "label": "The situation:"}, {"id": "f1", "type": "textarea", "label": "What I expected others to notice:"}, {"id": "f2", "type": "textarea", "label": "How much attention I thought I would get, 0 to 100:"}, {"id": "f3", "type": "textarea", "label": "What I actually saw them doing:"}, {"id": "f4", "type": "textarea", "label": "What I learned:"}]'::jsonb, array['social anxiety', 'behavioral experiment', 'thinking traps']::text[], '2026-11-08T15:00:00+00:00'::timestamptz),
  ('social-predictions-behavioral-test-log', 'Social Predictions Behavioral Test Log', 'cbt'::resource_kind, 'A log for predicting how a social moment will go, trying it and checking what happened.', 'Use it to help a client check social predictions against real outcomes.', array['Adults', 'Teens']::text[], '30 minutes to plan, then a week', 'The client writes a prediction such as "I will have nothing to say," rates it, does a small social step and records the result. Include safety behaviors that may be quietly shaping outcomes. Choose the next step by what they learned.', '[{"id": "f0", "type": "textarea", "label": "My prediction:"}, {"id": "f1", "type": "textarea", "label": "How sure I am, 0 to 100:"}, {"id": "f2", "type": "textarea", "label": "The social step I will try:"}, {"id": "f3", "type": "textarea", "label": "What happened:"}, {"id": "f4", "type": "textarea", "label": "What I will try next:"}]'::jsonb, array['social anxiety', 'behavioral experiment', 'exposure']::text[], '2026-11-08T15:00:00+00:00'::timestamptz),
  ('social-values-over-social-comfort-page', 'Social Values Over Social Comfort Page', 'act'::resource_kind, 'A page for choosing connection that matters over comfort when social fear shows up.', 'Use it to help a client choose a valued social step while feeling nervous.', array['Adults', 'Teens']::text[], '25 minutes', 'Ask what kind of friend or colleague the client wants to be and what fear has kept them from. Pick one step in that direction with nerves along. Willingness, not confidence, is the target.', '[{"id": "f0", "type": "textarea", "label": "The kind of person I want to be with others:"}, {"id": "f1", "type": "textarea", "label": "What my nerves have stopped me from:"}, {"id": "f2", "type": "textarea", "label": "A step in that direction:"}, {"id": "f3", "type": "textarea", "label": "What my mind will say about it:"}, {"id": "f4", "type": "textarea", "label": "How I will take the step anyway:"}]'::jsonb, array['social anxiety', 'values', 'willingness']::text[], '2026-11-08T15:00:00+00:00'::timestamptz),
  ('gentle-skills-for-social-situations-card', 'Gentle Skills for Social Situations Card', 'dbt'::resource_kind, 'A card using breathing, grounding and a kind phrase before and during social events.', 'Use it to help a client have a few quiet skills for social moments.', array['Adults', 'Teens']::text[], '20 minutes', 'Build a card with a breathing step before entering, a grounding move in the room and a kind phrase. Practice one in session. Review in the next visit what was used and what to change.', '[{"id": "f0", "type": "textarea", "label": "My step before I enter:"}, {"id": "f1", "type": "textarea", "label": "A grounding move I can do quietly:"}, {"id": "f2", "type": "textarea", "label": "A kind phrase for myself:"}, {"id": "f3", "type": "textarea", "label": "Where I will use this next:"}, {"id": "f4", "type": "textarea", "label": "How it went:"}]'::jsonb, array['social anxiety', 'skills', 'grounding']::text[], '2026-11-08T15:00:00+00:00'::timestamptz),
  ('different-ways-of-grieving-partner-talk-guide', 'Different Ways of Grieving Partner Talk Guide', 'couples'::resource_kind, 'A guide for partners who grieve in different ways to share what each needs without comparing.', 'Use it to help partners respect different ways of grieving and stay connected.', array['Couples']::text[], '35 minutes', 'Each partner says how they are grieving, such as talking, staying busy or needing quiet, and what they need from the other. Avoid ranking styles. Agree on one way to be together each week and one way to give space. If either partner has thoughts of self-harm, include 988 (call or text) and work through it in session.', '[{"id": "f0", "type": "textarea", "label": "Partner A: How I am grieving:"}, {"id": "f1", "type": "textarea", "label": "Partner B: How I am grieving:"}, {"id": "f2", "type": "textarea", "label": "Partner A: What I need from you:"}, {"id": "f3", "type": "textarea", "label": "Partner B: What I need from you:"}, {"id": "f4", "type": "textarea", "label": "One way we will be together this week:"}, {"id": "f5", "type": "textarea", "label": "If either of us feels unsafe, we can call or text 988:"}]'::jsonb, array['grief and loss', 'couples', 'support']::text[], '2026-11-08T15:00:00+00:00'::timestamptz),
  ('memory-box-for-someone-i-miss-craft', 'Memory Box for Someone I Miss Craft', 'kids'::resource_kind, 'A box a child decorates and fills with drawings, small keepsakes and memories of someone they miss.', 'Use it to help a child hold memories of a person or pet they have lost.', array['Children']::text[], '35 minutes', 'Provide a box and let the child decorate it and choose what goes inside. The parent shares a memory too. Follow the child''s pace and words, using plain language about death. Let the box be visited whenever they want.', '[{"id": "f0", "type": "textarea", "label": "Draw the person or pet you miss:"}, {"id": "f1", "type": "textarea", "label": "A memory you want to keep:"}, {"id": "f2", "type": "textarea", "label": "A feeling you have when you think of them:"}, {"id": "f3", "type": "textarea", "label": "Something to put in the box:"}, {"id": "f4", "type": "textarea", "label": "What parent can do when you miss them:"}]'::jsonb, array['grief and loss', 'children', 'craft']::text[], '2026-11-08T15:00:00+00:00'::timestamptz),
  ('remembering-together-story-stones-game', 'Remembering Together Story Stones Game', 'game'::resource_kind, 'A group game where players choose a stone, name a memory and pass it around in a circle.', 'Use it to help a group share memories of someone or something lost in a gentle way.', array['Groups', 'Adults', 'Teens']::text[], '35 minutes', 'Players choose a smooth stone and, in turn, share a memory or a word for what they miss and place it in a bowl. Anyone may pass. Debrief on what it was like to hear others, and close with something that gives comfort.', '[{"id": "f0", "type": "textarea", "label": "The stone I chose and why:"}, {"id": "f1", "type": "textarea", "label": "A memory I shared:"}, {"id": "f2", "type": "textarea", "label": "Something I heard that stayed with me:"}, {"id": "f3", "type": "textarea", "label": "What comforts me:"}, {"id": "f4", "type": "textarea", "label": "What I will do with the stone:"}]'::jsonb, array['grief and loss', 'group', 'connection']::text[], '2026-11-08T15:00:00+00:00'::timestamptz),
  ('waves-of-grief-timeline-page', 'Waves of Grief Timeline Page', 'worksheet'::resource_kind, 'A timeline page for marking waves of grief and what set them off or eased them.', 'Use it to help a client notice that grief comes in waves and find what helps.', array['Adults', 'Teens']::text[], '25 minutes', 'The client marks high and low days on a timeline and writes what stirred them, such as a song or a date. Look for what eased the waves. Make no promises about how long grief lasts. Normalize that the waves may return.', '[{"id": "f0", "type": "textarea", "label": "Days when grief felt big:"}, {"id": "f1", "type": "textarea", "label": "What stirred it:"}, {"id": "f2", "type": "textarea", "label": "Days it eased and what was happening:"}, {"id": "f3", "type": "textarea", "label": "What helps me when a wave comes:"}, {"id": "f4", "type": "textarea", "label": "Who I can be with:"}]'::jsonb, array['grief and loss', 'self-monitoring', 'coping skills']::text[], '2026-11-08T15:00:00+00:00'::timestamptz),
  ('should-have-and-if-only-thought-check', 'Should Have and If Only Thought Check', 'cbt'::resource_kind, 'A page for looking at "if only" and "should have" thoughts after a loss and finding a kinder view.', 'Use it to help a client examine guilt-laden thoughts after a loss with compassion.', array['Adults', 'Teens']::text[], '30 minutes', 'Write the "if only" thought and ask what the client knew at the time versus now. Ask what they would say to a friend. Do not push away real regret; make room for sorrow and the love behind it.', '[{"id": "f0", "type": "textarea", "label": "My \"if only\" thought:"}, {"id": "f1", "type": "textarea", "label": "What I knew then:"}, {"id": "f2", "type": "textarea", "label": "What I know now:"}, {"id": "f3", "type": "textarea", "label": "What I would say to a friend in my place:"}, {"id": "f4", "type": "textarea", "label": "A kinder way to hold it:"}]'::jsonb, array['grief and loss', 'thinking traps', 'self-compassion']::text[], '2026-11-08T15:00:00+00:00'::timestamptz),
  ('describe-and-validate-interpersonal-check-in-card', 'Describe and Validate Interpersonal Check-In Card', 'dbt'::resource_kind, 'A card with DBT steps for describing a problem, expressing feelings and asserting a request.', 'Use it to help a client plan a clear, calm request in a relationship.', array['Adults', 'Teens']::text[], '25 minutes', 'Walk through the card and have the client fill in each step for a real situation. Rehearse aloud and adjust. Offer a fallback if the other person says no, and plan how to stay steady either way.', '[{"id": "f0", "type": "textarea", "label": "The situation, facts only:"}, {"id": "f1", "type": "textarea", "label": "How I feel about it:"}, {"id": "f2", "type": "textarea", "label": "What I am asking for:"}, {"id": "f3", "type": "textarea", "label": "Why it would help us both:"}, {"id": "f4", "type": "textarea", "label": "What I will do if they say no:"}]'::jsonb, array['relationship issues', 'interpersonal effectiveness', 'core DBT']::text[], '2026-11-08T15:00:00+00:00'::timestamptz),
  ('soft-start-up-complaint-rewrite-practice', 'Soft Start Up Complaint Rewrite Practice', 'couples'::resource_kind, 'A practice sheet where partners rewrite harsh complaints into soft start-ups.', 'Use it to help partners raise concerns without blame.', array['Couples']::text[], '30 minutes', 'Partners take a real complaint and rewrite it with "I feel... about... and I need..." in place of blame. Practice the new version aloud. Notice how the listener responds and trade roles.', '[{"id": "f0", "type": "textarea", "label": "Partner A: A complaint in my usual words:"}, {"id": "f1", "type": "textarea", "label": "Partner A: A soft start-up version:"}, {"id": "f2", "type": "textarea", "label": "Partner B: A complaint in my usual words:"}, {"id": "f3", "type": "textarea", "label": "Partner B: A soft start-up version:"}, {"id": "f4", "type": "textarea", "label": "What changed when we said it softly:"}]'::jsonb, array['relationship issues', 'communication', 'Gottman']::text[], '2026-11-08T15:00:00+00:00'::timestamptz),
  ('family-feelings-weather-report-drawing', 'Family Feelings Weather Report Drawing', 'kids'::resource_kind, 'A drawing where each family member shows their feelings as weather and shares it at dinner.', 'Use it to help a family name feelings in a simple, shared way.', array['Children']::text[], '25 minutes', 'Each family member draws their weather for the day, such as sun, wind or storm, and shares it in turn at a set time. No fixing allowed. The parent models by sharing first. Keep it short enough to repeat.', '[{"id": "f0", "type": "textarea", "label": "Draw your weather today:"}, {"id": "f1", "type": "textarea", "label": "Why it is that weather:"}, {"id": "f2", "type": "textarea", "label": "What you noticed about others'' weather:"}, {"id": "f3", "type": "textarea", "label": "Something that could help a stormy day:"}, {"id": "f4", "type": "textarea", "label": "What parent does after the report:"}]'::jsonb, array['relationship issues', 'family', 'children']::text[], '2026-11-08T15:00:00+00:00'::timestamptz),
  ('repair-or-rupture-role-play-card-game', 'Repair or Rupture Role Play Card Game', 'game'::resource_kind, 'A group card game where players act out a small relationship misstep and try a repair.', 'Use it to help a group practice small repairs after a misstep.', array['Groups', 'Teens', 'Adults']::text[], '35 minutes', 'Players draw a scene such as a forgotten plan or a sharp remark and act the misstep and then a repair. The group suggests other repairs. Debrief on which repairs landed and how it feels to offer one.', '[{"id": "f0", "type": "textarea", "label": "The scene I drew:"}, {"id": "f1", "type": "textarea", "label": "The repair I tried:"}, {"id": "f2", "type": "textarea", "label": "How it landed:"}, {"id": "f3", "type": "textarea", "label": "Another repair I could try:"}, {"id": "f4", "type": "textarea", "label": "A repair I want to use this week:"}]'::jsonb, array['relationship issues', 'repair', 'group']::text[], '2026-11-08T15:00:00+00:00'::timestamptz),
  ('boundaries-and-values-in-relationships-page', 'Boundaries and Values in Relationships Page', 'act'::resource_kind, 'A page linking a boundary to a value and the words to say it.', 'Use it to help a client set a boundary that fits what they care about.', array['Adults', 'Teens']::text[], '25 minutes', 'Ask about a relationship where the client feels worn down and what they value. Choose a boundary, write the words and rehearse. Expect guilt to show up and name it as company rather than a stop sign.', '[{"id": "f0", "type": "textarea", "label": "A relationship where I feel stretched:"}, {"id": "f1", "type": "textarea", "label": "What I value there:"}, {"id": "f2", "type": "textarea", "label": "The boundary I would like:"}, {"id": "f3", "type": "textarea", "label": "The words I will use:"}, {"id": "f4", "type": "textarea", "label": "What my mind will say, and how I will respond:"}]'::jsonb, array['relationship issues', 'boundaries', 'values']::text[], '2026-11-08T15:00:00+00:00'::timestamptz),
  ('safe-people-and-safe-places-stabilizing-map', 'Safe People and Safe Places Stabilizing Map', 'worksheet'::resource_kind, 'A map of the people, places and activities that help a client feel safe and steady.', 'Use it to help a client see what already helps them feel safe in their daily life.', array['Adults', 'Teens']::text[], '25 minutes', 'Keep the focus on the present and what supports safety now. The client lists safe people, places and calming activities. Never ask for what happened. Go at their pace and ask what they want to add.', '[{"id": "f0", "type": "textarea", "label": "People who help me feel safe:"}, {"id": "f1", "type": "textarea", "label": "Places where I feel steadier:"}, {"id": "f2", "type": "textarea", "label": "Activities that calm me:"}, {"id": "f3", "type": "textarea", "label": "Something I could add:"}, {"id": "f4", "type": "textarea", "label": "Who I might tell if I feel unsafe:"}]'::jsonb, array['sexual abuse', 'safety', 'support']::text[], '2026-11-08T15:00:00+00:00'::timestamptz),
  ('present-moment-self-blame-gentle-check', 'Present Moment Self-Blame Gentle Check', 'cbt'::resource_kind, 'A sheet for noticing self-blame thoughts in the present and meeting them with compassion.', 'Use it to help a client meet self-blame with a kinder, more balanced voice.', array['Adults', 'Teens']::text[], '30 minutes', 'Work only with the thought as it shows up now, not the events. Ask what the client would tell a friend and what responsibility belongs to whom, in general terms. Stay with the voice and not the details. Pace to what they can bear and stop if they are overwhelmed.', '[{"id": "f0", "type": "textarea", "label": "A self-blaming thought that visits:"}, {"id": "f1", "type": "textarea", "label": "How it makes me feel:"}, {"id": "f2", "type": "textarea", "label": "What I would say to a friend with that thought:"}, {"id": "f3", "type": "textarea", "label": "A kinder thought I can try:"}, {"id": "f4", "type": "textarea", "label": "Who I can talk to if it gets heavy:"}, {"id": "f5", "type": "textarea", "label": "If I feel unsafe, I can call or text 988:"}]'::jsonb, array['sexual abuse', 'self-compassion', 'thinking traps']::text[], '2026-11-08T15:00:00+00:00'::timestamptz),
  ('body-welcome-gentle-noticing-practice', 'Body Welcome Gentle Noticing Practice', 'act'::resource_kind, 'A practice sheet for noticing the body in small, chosen moments of attention and a way to stop.', 'Use it to help a client reconnect with the body gently and on their terms.', array['Adults', 'Teens']::text[], '20 minutes', 'Offer choices at every step, such as eyes open or closed, and a way to stop. The client notices a neutral part, like hands or feet, for a short time. Expect some clients to want to skip it. That is fine.', '[{"id": "f0", "type": "textarea", "label": "A part of my body that feels neutral:"}, {"id": "f1", "type": "textarea", "label": "What I notice there for ten seconds:"}, {"id": "f2", "type": "textarea", "label": "How much I want to do, 0 to 10:"}, {"id": "f3", "type": "textarea", "label": "How I will stop or step away:"}, {"id": "f4", "type": "textarea", "label": "What helps me feel in charge:"}]'::jsonb, array['sexual abuse', 'mindfulness', 'pacing']::text[], '2026-11-08T15:00:00+00:00'::timestamptz),
  ('putting-safety-first-skills-plan', 'Putting Safety First Skills Plan', 'dbt'::resource_kind, 'A plan with distress-tolerance and support steps a client can reach for when memories or feelings spike.', 'Use it to help a client have skills and contacts ready when feelings spike.', array['Adults', 'Teens']::text[], '25 minutes', 'Build a short ordered plan: a grounding step, a soothing step and a contact. Include 988 (call or text) and a trusted person. Keep it present-focused, avoiding the past. Practice a step in the room and revise as needed.', '[{"id": "f0", "type": "textarea", "label": "What tells me I need my plan:"}, {"id": "f1", "type": "textarea", "label": "My first grounding step:"}, {"id": "f2", "type": "textarea", "label": "My soothing step:"}, {"id": "f3", "type": "textarea", "label": "A person I can contact:"}, {"id": "f4", "type": "textarea", "label": "If I feel unsafe, I can call or text 988:"}]'::jsonb, array['sexual abuse', 'safety', 'distress tolerance']::text[], '2026-11-08T15:00:00+00:00'::timestamptz),
  ('partner-support-boundaries-and-pacing-agreement', 'Partner Support Boundaries and Pacing Agreement', 'couples'::resource_kind, 'An agreement where a partner learns what the survivor wants, in what pace, without needing details.', 'Use it to help partners agree on pacing, consent and support, with no need for details.', array['Couples']::text[], '35 minutes', 'The partner who has experienced harm says what helps, what to avoid and how they want to signal a pause. The other listens and writes it down. Details of the past are not required. Either person can stop at any time.', '[{"id": "f0", "type": "textarea", "label": "Partner A: What helps me feel safe:"}, {"id": "f1", "type": "textarea", "label": "Partner A: What I would like to avoid:"}, {"id": "f2", "type": "textarea", "label": "Partner B: How I will support and respect it:"}, {"id": "f3", "type": "textarea", "label": "Our signal to pause:"}, {"id": "f4", "type": "textarea", "label": "What we will do for ourselves afterward:"}]'::jsonb, array['sexual abuse', 'support', 'couples']::text[], '2026-11-08T15:00:00+00:00'::timestamptz),
  ('coping-skills-treasure-hunt-drawing', 'Coping Skills Treasure Hunt Drawing', 'kids'::resource_kind, 'A drawing and hunt where a child finds coping skills hidden around a map.', 'Use it to help a child learn and remember a handful of coping skills.', array['Children']::text[], '30 minutes', 'Draw a treasure map with five spots, each hiding a coping skill such as breathing or a hug. The child hunts for them and tries each. A parent joins and picks a favorite. Put the map where it is visible.', '[{"id": "f0", "type": "textarea", "label": "Draw your treasure map:"}, {"id": "f1", "type": "textarea", "label": "The skill you found at each spot:"}, {"id": "f2", "type": "textarea", "label": "Your favorite one:"}, {"id": "f3", "type": "textarea", "label": "When you will use it:"}, {"id": "f4", "type": "textarea", "label": "What parent will do when you need it:"}]'::jsonb, array['coping skills', 'children', 'play']::text[], '2026-11-08T15:00:00+00:00'::timestamptz),
  ('act-out-a-coping-skill-relay', 'Act Out a Coping Skill Relay', 'game'::resource_kind, 'A relay where teams act out a coping skill for others to guess and then try.', 'Use it to help a group learn each other''s coping skills and try new ones.', array['Groups', 'Teens', 'Children']::text[], '30 minutes', 'Teams act out a coping skill such as stretching or a walk, with the rest guessing. After each round everyone tries it for thirty seconds. Debrief on what they would add to their own list.', '[{"id": "f0", "type": "textarea", "label": "The skill I acted:"}, {"id": "f1", "type": "textarea", "label": "The skill I would like to try:"}, {"id": "f2", "type": "textarea", "label": "When I might use it:"}, {"id": "f3", "type": "textarea", "label": "A skill I will add to my list:"}, {"id": "f4", "type": "textarea", "label": "What I learned from others:"}]'::jsonb, array['coping skills', 'group', 'play']::text[], '2026-11-08T15:00:00+00:00'::timestamptz),
  ('feeling-size-coping-menu', 'Feeling Size Coping Menu', 'worksheet'::resource_kind, 'A menu of coping skills sorted by feeling level, from mild to very strong.', 'Use it to help a client match a coping skill to how big the feeling is.', array['Adults', 'Teens']::text[], '25 minutes', 'Make three columns for mild, medium and strong feelings and fill each with skills the client already uses or wants to try. Strong feelings need fast, body-based skills. Revisit the menu to refine it.', '[{"id": "f0", "type": "textarea", "label": "Skills for mild feelings:"}, {"id": "f1", "type": "textarea", "label": "Skills for medium feelings:"}, {"id": "f2", "type": "textarea", "label": "Skills for strong feelings:"}, {"id": "f3", "type": "textarea", "label": "A skill I want to try:"}, {"id": "f4", "type": "textarea", "label": "Where I will keep this menu:"}]'::jsonb, array['coping skills', 'regulation', 'planning']::text[], '2026-11-08T15:00:00+00:00'::timestamptz),
  ('coping-thoughts-index-card-builder', 'Coping Thoughts Index Card Builder', 'cbt'::resource_kind, 'A builder for index cards with short coping statements that the client can carry.', 'Use it to help a client carry coping statements in their own words.', array['Adults', 'Teens']::text[], '25 minutes', 'Pick three hard situations and write a short, believable statement for each, not a cheerful one. Test each by asking whether the client could say it with a straight face. Put them on cards for the pocket or phone.', '[{"id": "f0", "type": "textarea", "label": "A hard situation:"}, {"id": "f1", "type": "textarea", "label": "What I tell myself that makes it worse:"}, {"id": "f2", "type": "textarea", "label": "A coping statement I believe:"}, {"id": "f3", "type": "textarea", "label": "A second situation and statement:"}, {"id": "f4", "type": "textarea", "label": "Where I will keep my cards:"}]'::jsonb, array['coping skills', 'self-talk', 'core CBT']::text[], '2026-11-08T15:00:00+00:00'::timestamptz),
  ('coping-versus-control-strategy-review', 'Coping Versus Control Strategy Review', 'act'::resource_kind, 'A review of the strategies a client uses to feel better and what they cost in the long run.', 'Use it to help a client see which coping strategies serve their values over time.', array['Adults', 'Teens']::text[], '30 minutes', 'List strategies the client uses and rate short-term relief and long-term cost. Avoid moralizing; most strategies have a place. Ask which ones pull them toward the life they want and which pull away, and choose one to adjust.', '[{"id": "f0", "type": "textarea", "label": "Strategies I use when I feel bad:"}, {"id": "f1", "type": "textarea", "label": "How well each helps in the moment:"}, {"id": "f2", "type": "textarea", "label": "What each costs me over time:"}, {"id": "f3", "type": "textarea", "label": "Ones that move me toward what matters:"}, {"id": "f4", "type": "textarea", "label": "One I will adjust:"}]'::jsonb, array['coping skills', 'values', 'workability']::text[], '2026-11-08T15:00:00+00:00'::timestamptz),
  ('fear-ladder-distress-tolerance-card', 'Fear Ladder Distress Tolerance Card', 'dbt'::resource_kind, 'A card with skills to use at each rung of a graded fear ladder.', 'Use it to help a client pair distress-tolerance skills with each step of a fear ladder.', array['Adults', 'Teens']::text[], '30 minutes', 'Build a short ladder from mild to harder steps and assign a skill to use at each, such as paced breathing before and grounding during. Start at a mild rung. Celebrate staying, not the absence of fear.', '[{"id": "f0", "type": "textarea", "label": "The feared thing:"}, {"id": "f1", "type": "textarea", "label": "Steps from mild to hard:"}, {"id": "f2", "type": "textarea", "label": "A skill I will use at each step:"}, {"id": "f3", "type": "textarea", "label": "My first step this week:"}, {"id": "f4", "type": "textarea", "label": "What I noticed afterward:"}]'::jsonb, array['phobias', 'distress tolerance', 'exposure']::text[], '2026-11-08T15:00:00+00:00'::timestamptz),
  ('supporting-a-partner-through-a-fear-step-guide', 'Supporting a Partner Through a Fear Step Guide', 'couples'::resource_kind, 'A guide where one partner coaches and cheers on the other through a fear step without taking over.', 'Use it to help partners support a feared step without rescuing or pushing.', array['Couples']::text[], '30 minutes', 'The partner facing the fear picks a step and says how they want help. The other practices a calm, encouraging stance. Plan the debrief ahead of time. Agree that the person facing it sets the pace.', '[{"id": "f0", "type": "textarea", "label": "Partner A: The step I will take:"}, {"id": "f1", "type": "textarea", "label": "Partner A: How I want to be supported:"}, {"id": "f2", "type": "textarea", "label": "Partner B: What I will say and do:"}, {"id": "f3", "type": "textarea", "label": "What we will do if it feels too hard:"}, {"id": "f4", "type": "textarea", "label": "How we will celebrate the effort:"}]'::jsonb, array['phobias', 'support', 'couples']::text[], '2026-11-08T15:00:00+00:00'::timestamptz),
  ('fear-fighter-hero-drawing-and-step-chart', 'Fear Fighter Hero Drawing and Step Chart', 'kids'::resource_kind, 'A drawing of a hero who faces a fear plus a chart of small steps.', 'Use it to help a child plan brave small steps toward a feared thing.', array['Children']::text[], '35 minutes', 'The child draws a hero version of themselves and a staircase of small steps. The parent agrees on the first step, cheers without forcing, and uses stickers for tries. Keep steps small and fun, and go no faster than the child can manage.', '[{"id": "f0", "type": "textarea", "label": "Draw your fear fighter hero:"}, {"id": "f1", "type": "textarea", "label": "The thing you are scared of:"}, {"id": "f2", "type": "textarea", "label": "Your small steps, from easy to hard:"}, {"id": "f3", "type": "textarea", "label": "What your hero says to the fear:"}, {"id": "f4", "type": "textarea", "label": "What parent does to cheer you on:"}]'::jsonb, array['phobias', 'children', 'exposure']::text[], '2026-11-08T15:00:00+00:00'::timestamptz),
  ('rung-by-rung-fear-steps-board-game', 'Rung by Rung Fear Steps Board Game', 'game'::resource_kind, 'A board game where players climb a ladder by trying small tasks and rolling a die.', 'Use it to help a group practice small tasks toward feared things in a playful way.', array['Groups', 'Teens', 'Children']::text[], '35 minutes', 'Each player has a personal ladder of mild tasks chosen with the clinician. A roll picks which task to try or whether to cheer a friend. Passing is allowed. Debrief on what it was like to try and to cheer.', '[{"id": "f0", "type": "textarea", "label": "The task I tried:"}, {"id": "f1", "type": "textarea", "label": "What my fear said:"}, {"id": "f2", "type": "textarea", "label": "What happened:"}, {"id": "f3", "type": "textarea", "label": "Who I cheered for:"}, {"id": "f4", "type": "textarea", "label": "The next task I will try:"}]'::jsonb, array['phobias', 'group', 'exposure']::text[], '2026-11-08T15:00:00+00:00'::timestamptz),
  ('avoidance-cost-and-benefit-page-for-a-specific-fear', 'Avoidance Cost and Benefit Page for a Specific Fear', 'worksheet'::resource_kind, 'A page weighing what avoiding a specific fear gives and costs.', 'Use it to help a client see how avoidance shapes their life and decide on one step.', array['Adults', 'Teens']::text[], '25 minutes', 'Name one specific fear and the ways the client avoids it. List short-term relief and long-term costs. The page leads toward one step on the client''s own timeline, never ahead of what they are ready for.', '[{"id": "f0", "type": "textarea", "label": "The fear and how I avoid it:"}, {"id": "f1", "type": "textarea", "label": "What avoiding gives me:"}, {"id": "f2", "type": "textarea", "label": "What avoiding costs me:"}, {"id": "f3", "type": "textarea", "label": "What I would do if the fear were smaller:"}, {"id": "f4", "type": "textarea", "label": "One step I might take:"}]'::jsonb, array['phobias', 'avoidance', 'exposure']::text[], '2026-11-08T15:00:00+00:00'::timestamptz),
  ('appearance-thoughts-reframe-sheet', 'Appearance Thoughts Reframe Sheet', 'cbt'::resource_kind, 'A sheet for catching harsh thoughts about appearance and trying fairer ones that do not rely on looks.', 'Use it to help a client loosen the grip of appearance thoughts.', array['Adults', 'Teens']::text[], '30 minutes', 'Have the client catch a thought about how they look and write what it makes them do. Ask what else is true about them and what they would tell a friend. Keep the focus on thoughts and actions, not on the body itself, and avoid arguing about appearance.', '[{"id": "f0", "type": "textarea", "label": "The thought about how I look:"}, {"id": "f1", "type": "textarea", "label": "What it makes me do or avoid:"}, {"id": "f2", "type": "textarea", "label": "Something else that is true about me:"}, {"id": "f3", "type": "textarea", "label": "What I would tell a friend:"}, {"id": "f4", "type": "textarea", "label": "A fairer thought I can try:"}]'::jsonb, array['body image', 'thinking traps', 'self-talk']::text[], '2026-11-08T15:00:00+00:00'::timestamptz),
  ('body-as-a-home-not-a-display-page', 'Body as a Home Not a Display Page', 'act'::resource_kind, 'A page for relating to the body as a place to live in, with a value-driven action.', 'Use it to help a client treat their body as a home for living rather than something on display.', array['Adults', 'Teens']::text[], '25 minutes', 'Ask what the client''s body lets them do and what they hold back from because of how they feel about it. Choose a valued action to do with discomfort along. Keep it off judging appearance and focus on living.', '[{"id": "f0", "type": "textarea", "label": "What my body lets me do:"}, {"id": "f1", "type": "textarea", "label": "What I hold back from:"}, {"id": "f2", "type": "textarea", "label": "What I value that I would do anyway:"}, {"id": "f3", "type": "textarea", "label": "A step I will take:"}, {"id": "f4", "type": "textarea", "label": "What I notice when I do it:"}]'::jsonb, array['body image', 'values', 'willingness']::text[], '2026-11-08T15:00:00+00:00'::timestamptz),
  ('self-soothing-with-kindness-toward-my-body-card', 'Self-Soothing With Kindness Toward My Body Card', 'dbt'::resource_kind, 'A card of soothing, kind actions toward the body such as warmth, rest and gentle movement.', 'Use it to help a client find soothing, caring actions that are not about how they look.', array['Adults', 'Teens']::text[], '20 minutes', 'Build the card with soothing moves for the senses, such as a warm shower or a soft blanket, and kind words. Keep it all about comfort and care. Practice one in session and revise what does not suit the client.', '[{"id": "f0", "type": "textarea", "label": "A soothing thing I can feel:"}, {"id": "f1", "type": "textarea", "label": "A soothing thing I can hear or see:"}, {"id": "f2", "type": "textarea", "label": "A kind phrase for my body:"}, {"id": "f3", "type": "textarea", "label": "When I will use my card:"}, {"id": "f4", "type": "textarea", "label": "What I noticed afterward:"}]'::jsonb, array['body image', 'self-soothing', 'skills']::text[], '2026-11-08T15:00:00+00:00'::timestamptz),
  ('partner-words-that-help-page', 'Partner Words That Help Page', 'couples'::resource_kind, 'A page where partners say which words and tones help when a person feels low about their looks.', 'Use it to help partners support each other without focusing on appearance.', array['Couples']::text[], '30 minutes', 'Each partner says what comments help and what makes things worse when they feel down about how they look. Agree on a way to turn attention to what they value in each other. Keep the talk on words and actions and never on bodies.', '[{"id": "f0", "type": "textarea", "label": "Partner A: Words that help me:"}, {"id": "f1", "type": "textarea", "label": "Partner A: Words that do not:"}, {"id": "f2", "type": "textarea", "label": "Partner B: Words that help me:"}, {"id": "f3", "type": "textarea", "label": "Partner B: Words that do not:"}, {"id": "f4", "type": "textarea", "label": "What we will say instead:"}]'::jsonb, array['body image', 'communication', 'couples']::text[], '2026-11-08T15:00:00+00:00'::timestamptz),
  ('my-body-can-poster-craft', 'My Body Can Poster Craft', 'kids'::resource_kind, 'A poster a child draws and decorates of all the things their body can do.', 'Use it to help a child notice and celebrate what their body lets them do.', array['Children']::text[], '30 minutes', 'The child draws or cuts out activities such as running, hugging and playing music and decorates a poster. The parent adds a few ideas and keeps comments off appearance. Display it somewhere they will see it.', '[{"id": "f0", "type": "textarea", "label": "Draw or paste what your body can do:"}, {"id": "f1", "type": "textarea", "label": "Your favorite thing:"}, {"id": "f2", "type": "textarea", "label": "A thing you want to try:"}, {"id": "f3", "type": "textarea", "label": "How you feel doing it:"}, {"id": "f4", "type": "textarea", "label": "What parent added to your poster:"}]'::jsonb, array['body image', 'children', 'strengths']::text[], '2026-11-08T15:00:00+00:00'::timestamptz)
